import { Col, Input, Row, Table } from 'antd'
import PropTypes from 'prop-types'
import { ViewInstalmentsStyle } from './index.style'
import FormItem from 'antd/lib/form/FormItem'
import { LANG } from '../InstalmentsForm/constants'
import { columns } from './constants'

const ViewInstalments = (props) => {
  const { instalmentsData, isPolicy = false, policyColumns } = props
  const { instalment_period: instalmentPeriod, total_instalments: totalInstalments, instalment_details: instalmentDetails } = instalmentsData

  return (
    <ViewInstalmentsStyle>
      <Row type='flex' justify='start' gutter={24}>
        <Col>
          <FormItem
            name='period'
            label={LANG.onlyPeriod}
            colon={false}
          >
            <Input disabled value={`${instalmentPeriod} Bulan`} />
          </FormItem>
        </Col>
        <Col>
          <FormItem
            name='instalment_amount'
            label={LANG.instalmentAmount}
            colon={false}
          >
            <Input disabled value={`${totalInstalments} Kali`} />
          </FormItem>
        </Col>
      </Row>
      <Table
        size='small' dataSource={instalmentDetails}
        pagination={{ position: 'none', pageSize: 12 }}
        scroll={{ x: true, y: true }}
        columns={isPolicy ? policyColumns : columns}
        className='instalments-table'
        rowKey={(record) => record.serial_number}
      />
    </ViewInstalmentsStyle>
  )
}

ViewInstalments.propTypes = {
  instalmentsData: PropTypes.shape({
    instalment_period: PropTypes.number,
    total_instalments: PropTypes.number,
    instalment_details: PropTypes.array
  }),
  isPolicy: PropTypes.bool,
  policyColumns: PropTypes.array
}

export default ViewInstalments
