import { Button } from 'antd'
import moment from 'moment-timezone'
import { formatIntlCurrency } from '../../../../../../helpers/utility'
import { LANG } from '../../../OfflineQuotes/pages/OfflineQuoteDetails/components/InstalmentsForm/constants'

export const policyColumns = (handleViewDocument, handleGenerateInvoice) => [
  {
    title: LANG.instalmentNo,
    dataIndex: 'serial_number',
    key: 'serial_number',
    width: '96px'
  },
  {
    title: LANG.dueDate,
    dataIndex: 'due_date',
    key: 'due_date',
    width: '180px',
    render: (text, record, index) => moment(record.due_date).format('LL')
  },
  {
    title: LANG.totalInstalmentAmount,
    dataIndex: 'payable_amount',
    key: 'payabl_amount',
    width: '160px',
    render: (text, record, index) => formatIntlCurrency(record.payable_amount)
  },
  {
    title: 'Invoice',
    dataIndex: 'invoice_url',
    key: 'invoice_url',
    width: '128px',
    render: (text, record, index) => {
      const value = record.invoice_url
      if (value) {
        return (
          <Button onClick={() => handleViewDocument({
            url: value,
            title: 'Invoice'
          })}
          >
            View Invoice
          </Button>
        )
      }
      if (record.isGenerate) {
        return (
          <Button onClick={() => handleGenerateInvoice(record)}>Generate</Button>
        )
      }

      return '-'
    }
  },
  {
    title: 'Payment By',
    dataIndex: 'payment_by',
    key: 'payment_by',
    width: '128px',
    render: (text, record, index) => record.payment_by || '-'
  },
  {
    title: 'Transfer To',
    dataIndex: 'paid_to',
    key: 'paid_to',
    width: '128px',
    render: (text, record, index) => record.paid_to || '-'
  },
  {
    title: 'Transfer Amount',
    dataIndex: 'paid_amount',
    key: 'paid_amount',
    width: '160px',
    render: (text, record, index) => record.paid_amount ? formatIntlCurrency(record.paid_amount) : '-'
  },
  {
    title: 'Payment Date',
    dataIndex: 'payment_date',
    key: 'payment_date',
    width: '140px',
    render: (text, record, index) => record.payment_date ? moment(record.payment_date).format('LL') : '-'
  },
  {
    title: 'Payment Method',
    dataIndex: 'payment_method',
    key: 'payment_method',
    width: '140px',
    render: (text, record, index) => record.payment_method || '-'
  },
  {
    title: 'Payment Proof',
    dataIndex: 'payment_proof_url',
    key: 'payment_proof_url',
    width: '128px',
    render: (text, record, index) => {
      const value = record.payment_proof_url
      if (value) {
        return (
          <Button onClick={() => handleViewDocument({
            url: value,
            title: 'Payment Proof'
          })}
          >
            View
          </Button>
        )
      }
      return '-'
    }
  },
  {
    title: 'Payment Status',
    dataIndex: 'payment_status',
    key: 'payment_status',
    width: '160px',
    render: (text, record, index) => record.payment_status || '-'
  }
]
