import React, { useCallback, useMemo } from 'react'
import {
  Row,
  Col,
  Table,
  Button,
  Upload,
  Tag
} from 'antd'
import PropTypes from 'prop-types'
import { capitalizeFirstLetter } from '../../../../../../helpers/utility'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import ModalImage from 'react-modal-image'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import get from 'lodash/get'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

function ImageTable (props) {
  const { isRenewalPolicy, isShowEditBtn, onEdit,imagesVerify } = props
  const handleImageInfo = useCallback((data) => {
    props.onImageInfo(data)
  }, [props])

  const handleTheReupload = useCallback((data, key, file) => {
    // handle the Reupload
    if (props.onReupload) {
      props.onReupload({ data, key, file })
    }
  }, [props])

  const columns = useMemo(() => ([
    {
      title: 'Document Name',
      dataIndex: 'name',
      width: 150
    },
    {
      title: 'OCR status', width: 100, dataIndex: 'ocr_status', key: 'ocr_status', render: (_, record) => {
        const isOcrVerified = imagesVerify ? imagesVerify[record?.id] : false
        if (isOcrVerified) {
          return (
            <Tag color="green">Verified</Tag>
          )
        } else {
          return null
        }
      }
    },
    {
      title: 'Photo',
      dataIndex: 'value'
    },

    {
      title: 'Reupload Document',
      dataIndex: 'reupload_document',
      key: 'reupload_document'
    },
    ...(isShowEditBtn)
      ? [
          {
            title: 'Edit photo',
            dataIndex: '',
            key: 'y',
            render: (data) => {
              return (
                <PermissionCheckerV2 requiredPermission='ops.edit_timestamp'>
                  <Button title='Edit Timestamp' onClick={() => onEdit({ id: data?.id, link: props?.imagesData[data?.id] })}> Edit </Button>
                </PermissionCheckerV2>
              )
            }
          }
        ]
      : [],
    {
      title: 'Image Meta data',
      dataIndex: '',
      key: 'x',
      render: (data) => {
        if (get(data, 'value.props.small', '')) {
          return (
            <div onClick={() => handleImageInfo(data)}>Info</div>
          )
        }
        return null
      }
    }
  ]
  ), [isShowEditBtn, imagesVerify, onEdit, props?.imagesData, handleImageInfo])

  const imageData = useMemo(() => {
    let imagesMap = []
    let count = 0
    for (const key in props.imagesData) {
      const data = props.imagesData[key]
      let type = 'image'
      if (props.imagesType) {
        type = props.imagesType[key]
      }
      const fileExt = getUrlExtension(data)
      let fileType = '.jpg,.png,.jpeg'
      if (type === 'pdf') {
        fileType = `${fileType},.pdf`
      }
      if (data || (isRenewalPolicy && (key === 'appointment_letter_url'))) {
        imagesMap = [
          ...imagesMap, {
            key: count,
            name: <strong>{capitalizeFirstLetter(key)}</strong>,
            id: key,
            value: type === 'link'
              ? (
                <a href={data} target='_blank' rel='noopener noreferrer'>View Policy</a>
                )
              : fileExt === 'pdf'
              ? (
                <a href={data} target='_blank' id={key} rel='noopener noreferrer'>
                  <object
                    type='application/pdf'
                    data={data}
                    width='150'
                    height='150'
                    aria-label='PDF'
                  />
                </a>
                )
              : (

                <ModalImage
                  className={`object-image ${key}`}
                  small={data}
                  large={data}
                  id={key}
                  name={key}
                />
                ),
            reupload_document: props.isShowReuploadBtn && (
              <PermissionCheckerV2 requiredPermission='ops.view_agent_policy_reupload_documents_btn'>
                <Upload
                  name='file'
                  accept={fileType}
                  multiple={false}
                  showUploadList={false}
                  customRequest={({ file }) => handleTheReupload(data, key, file)}
                >
                  <Button>
                    {data ? 'Reupload' : 'Upload'} Document
                  </Button>
                </Upload>
              </PermissionCheckerV2>
            )
          }
        ]
        count++
      }
    }
    return imagesMap
  }, [props.imagesData, handleTheReupload,
    props.isShowReuploadBtn, isRenewalPolicy,
    props.imagesType
  ])

  return (
    <LayoutContent className='details-info-container policy-detail-card'>
      <Row>
        <h3 className='policy-title'>{props.title}</h3>
        <Col span={24}>
          <Table
            pagination={{ pageSize: 100 }}
            showHeader={false}
            columns={columns}
            dataSource={imageData}
          />
        </Col>
      </Row>
    </LayoutContent>
  )
}

ImageTable.propTypes = {
  title: PropTypes.string,
  isShowReuploadBtn: PropTypes.bool,
  imagesData: PropTypes.object,
  imagesVerify: PropTypes.object,
  onImageInfo: PropTypes.func,
  onReupload: PropTypes.func
}

export default ImageTable
