import { useResetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useGetInstalmentDetails, useGenerateInstalmentInvoice } from '../../state/hooks/useAgentPolicyState'
import { Form, Modal, Row } from 'antd'
import get from 'lodash/get'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Lightbox } from 'react-modal-image'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent.style'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import ViewInstalments from '../../../OfflineQuotes/pages/OfflineQuoteDetails/components/ViewInstalments'
import { policyColumns } from './constants'
import { InvoiceModalStyle } from './index.style'
import CircularLoader from '../../../../../../components/CircularLoader'
import { showNotification } from '../../../../../../components/ShowNotification'

const ViewPolicyInstalments = props => {
  const { form, agentPolicyDetails } = props
  const applicationId = get(agentPolicyDetails, 'id')
  const { getFieldDecorator, getFieldValue, resetFields } = form
  const [{ getInstalmentDetailsData }, getInstalmentDetailsRequest] = useGetInstalmentDetails()
  const [, generateInstalmentInvoiceRequest] = useGenerateInstalmentInvoice()
  const [{ GET_INSTALMENT_DETAILS_LOADER, GENERATE_INSTALMENT_INVOICE_LOADER }] = useLoaderContextValue()
  const [{ getInstalmentDetailsStatus, generateInstalmentInvoiceStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  useEffect(() => {
    if (applicationId) {
      getInstalmentDetailsRequest({
        applicationId
      })
    }
  }, [getInstalmentDetailsRequest, applicationId])

  const renderFormItems = useCallback((item) => {
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: getFieldDecorator,
      getFieldValue: getFieldValue
    })
  }, [getFieldDecorator, getFieldValue])
  const fileUrl = useRef({
    url: '',
    title: ''
  })
  const finalInstalmentsData = useMemo(() => {
    if (!getInstalmentDetailsData || !Object.keys(getInstalmentDetailsData).length) return undefined
    let instalmentsData = getInstalmentDetailsData
    const instalmentDetails = get(instalmentsData, 'instalment_details')
    instalmentsData = {
      ...instalmentsData,
      instalment_details: instalmentDetails.map((x, i) => {
        if (i === 0 || instalmentDetails[i - 1]?.transaction_status === 'PAID') {
          return {
            ...x,
            isGenerate: true
          }
        } else {
          return x
        }
      })
    }
    return instalmentsData
  }, [getInstalmentDetailsData])
  const generateData = useRef({})
  const [showFile, setShowFile] = useState(false)
  const [showGenerate, setShowGenerate] = useState(false)
  const handleViewDocument = (documentUrl) => {
    fileUrl.current = documentUrl
    setShowFile(true)
  }
  const handleGenerateInvoice = (data) => {
    generateData.current = data
    setShowGenerate(true)
  }
  const handleGenerateInvoiceRequest = () => {
    const gd = generateData.current
    const body = {
      serial_number: gd.serial_number,
      due_date: gd.due_date,
      payable_amount: gd.payable_amount,
      payment_by: getFieldValue('payment_by')
    }
    generateInstalmentInvoiceRequest({
      applicationId,
      body
    })
  }
  const renderDocument = () => {
    const { url, title } = fileUrl.current
    const fileExt = getUrlExtension(url)
    const onCancel = () => {
      fileUrl.current = {
        url: '',
        title: ''
      }
      setShowFile(false)
    }
    if (fileExt === 'pdf') {
      return (
        <Modal
          visible={showFile}
          onCancel={onCancel}
          style={{ top: 0 }}
          width='100vw'
          footer={null}
        >
          <InvoiceModalStyle>
            <Row type='flex' justify='center'>
              <iframe src={url} title={title} className='invoice-iframe' />
            </Row>
          </InvoiceModalStyle>
        </Modal>
      )
    } else {
      return (
        <Lightbox
          medium={url}
          large={url}
          alt={title}
          onClose={onCancel}
        />
      )
    }
  }

  const onCancel = useCallback(() => {
    generateData.current = {}
    resetFields()
    setShowGenerate(false)
  }, [resetFields])

  useEffect(() => {
    if (generateInstalmentInvoiceStatus === 'success') {
      showNotification('success', 'invoice generated successfully')
      resetError(['generateInstalmentInvoiceStatus'])
      getInstalmentDetailsRequest({
        applicationId
      })
      onCancel()
    } else if (generateInstalmentInvoiceStatus) {
      showNotification('error', generateInstalmentInvoiceStatus)
      resetError(['generateInstalmentInvoiceStatus'])
    }
  }, [generateInstalmentInvoiceStatus, applicationId,
    getInstalmentDetailsRequest, onCancel, resetError])

  useEffect(() => {
    if (getInstalmentDetailsStatus === 'success') {
      resetError(['getInstalmentDetailsStatus'])
    } else if (getInstalmentDetailsStatus) {
      showNotification('error', getInstalmentDetailsStatus)
      resetError(['getInstalmentDetailsStatus'])
    }
  }, [getInstalmentDetailsStatus, resetError])

  if (!finalInstalmentsData) {
    return null
  }

  return (
    <LayoutContentStyle className='details-info-container policy-detail-card'>
      <h3 className='policy-title'>Payment Information</h3>
      <CircularLoader isSpinning={GET_INSTALMENT_DETAILS_LOADER}>
        {finalInstalmentsData && <ViewInstalments instalmentsData={finalInstalmentsData} isPolicy policyColumns={policyColumns(handleViewDocument, handleGenerateInvoice)} />}
        {showFile && renderDocument()}
        {showGenerate && (
          <Modal
            visible={showGenerate}
            onCancel={onCancel}
            onOk={handleGenerateInvoiceRequest}
            cancelButtonProps={{
              disabled: GENERATE_INSTALMENT_INVOICE_LOADER
            }}
            okButtonProps={{
              disabled: !getFieldValue('payment_by') || GENERATE_INSTALMENT_INVOICE_LOADER
            }}
          >
            <CircularLoader isSpinning={GENERATE_INSTALMENT_INVOICE_LOADER}>
              <Form colon={false}>
                {
                  renderFormItems({
                    name: 'payment_by',
                    radioDataKey: 'payment_by',
                    title: 'Who will purchase the invoice?',
                    subTitle: 'payment_by',
                    type: 'hybrid_radio',
                    required: true,
                    isKeyDisabled: () => true,
                    isEnableType: true,
                    onlyRadio: true,
                    runtimeRequestParams: {},
                    handleRuntimeParams: (data) => {
                    },
                    data: [
                      {
                        value: 'MITRA',
                        title: 'Agent'
                      },
                      {
                        value: 'CUSTOMER',
                        title: 'Customer'
                      }
                    ]
                  })
                }
              </Form>
              <i>The policy will be issued once you click the submit button.</i>
            </CircularLoader>
          </Modal>
        )}
      </CircularLoader>
    </LayoutContentStyle>
  )
}

const WrappedViewPolicyInstalments = Form.create()(ViewPolicyInstalments)
export default WrappedViewPolicyInstalments
