import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { DatePicker, Form, Input, Modal, Select, Row, Col, Upload, Button, Icon } from 'antd'
import { HardCopyStatusModalStyle } from './index.style'
import { get } from 'lodash'
import { connect } from 'react-redux'
import agentActions from '../../../../../redux/agent/actions'
import policyActions from '../../../../../../redux/policy/actions'
import moment from 'moment'
import { showNotification } from '../../../../../../components/ShowNotification'
import isVNPath from '../../../../../../helpers/isVNPath'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../constants'

const { updateHardCopyDate } = agentActions
const { uploadPolicyFile, resetReduxState: policyResetReduxState } = policyActions

class HardCopyStatusModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    policy: PropTypes.object,
    onClose: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 12 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 12 }
      }
    }
    this.isCourierEnabled = true
    this.state = {
      orderType: null,
      trackingDocumentUrl: null,
      isUploading: false
    }
    this.prevShowModal = props.showModal
  }

  componentDidUpdate (prevProps) {
    // Reset state when modal closes
    if (prevProps.showModal && !this.props.showModal) {
      this.setState({ 
        orderType: null, 
        trackingDocumentUrl: null,
        isUploading: false
      })
    }
    
    // Handle file upload response
    if (prevProps.uploadPolicyFileStatus !== this.props.uploadPolicyFileStatus) {
      if (this.props.uploadPolicyFileStatus === 'success') {
        const uploadedUrl = this.props.uploadPolicyFileData?.url
        if (uploadedUrl) {
          this.setState({ 
            trackingDocumentUrl: uploadedUrl,
            isUploading: false
          })
          // Update form field with the URL
          this.props.form.setFieldsValue({
            hard_copy_existing_tracking_label_url: uploadedUrl
          })
          showNotification('success', 'File uploaded successfully')
        }
        // Clear the policy store after successful upload
        policyResetReduxState(['uploadPolicyFileStatus', 'uploadPolicyFileData'])
      } else if (this.props.uploadPolicyFileStatus && this.props.uploadPolicyFileStatus !== 'success') {
        this.setState({ isUploading: false })
        const errorMessage = this.props.uploadPolicyFileStatus || 'File upload failed. Please try again.'
        showNotification('error', errorMessage)
        // Clear the policy store after failed upload
        policyResetReduxState(['uploadPolicyFileStatus', 'uploadPolicyFileData'])
      }
    }
    
    this.prevShowModal = this.props.showModal
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleDisabledDate = (current, disabledDate) => {
    if ((current > moment().endOf('day'))) {
      return true
    }
    if (disabledDate) {
      return current && (current < moment(disabledDate).add(-1, 'day').endOf('day'))
    }

    return false
  }

  handleSubmitData = async (e) => {
    // handle data
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) return
    
    const { uploadPolicyFileLoading } = this.props
    if (this.state.isUploading || uploadPolicyFileLoading) {
      showNotification('error', 'Please wait for file upload to complete')
      return
    }
    
    const { form, policy = {} } = this.props
    const formValues = form.getFieldsValue()
    const deliveryType = formValues.type_of_delivery
    const orderType = formValues.hard_copy_order_type
    
    const requestBody = {
      hard_copy_sent_date: moment(formValues.hard_copy_sent_date).format('YYYY-MM-DD'),
      type_of_delivery: deliveryType,
      hard_copy_recipient: formValues.hard_copy_recipient,
      hard_copy_recipient_mobile: formValues.hard_copy_recipient_mobile,
      referenceId: policy.reference_id
    }
    
    if (formValues.hard_copy_receive_date) {
      requestBody.hard_copy_receive_date = moment(formValues.hard_copy_receive_date).format('YYYY-MM-DD')
    }
    
    if (formValues.hard_copy_remarks) {
      if (formValues.hard_copy_remarks.length > 500) {
        showNotification('error', 'Maximum 500 character allowed for the hard copy information')
        return
      }
      requestBody.hard_copy_remarks = formValues.hard_copy_remarks
    }
    
    // Add order type when delivery type is 'shipped-by-pp'
    if (deliveryType === 'shipped-by-pp') {
      requestBody.hard_copy_order_type = orderType ? orderType.toLowerCase() : null
      
      // Add tracking fields when order type is 'group'
      if (orderType && orderType.toLowerCase() === 'group') {
        if (!formValues.hard_copy_existing_tracking_number) {
          showNotification('error', 'Please enter tracking number')
          return
        }
        requestBody.hard_copy_existing_tracking_number = formValues.hard_copy_existing_tracking_number
        
        // Use the uploaded URL from state or form value
        const trackingUrl = this.state.trackingDocumentUrl || formValues.hard_copy_existing_tracking_label_url
        if (!trackingUrl) {
          showNotification('error', 'Please upload tracking document')
          return
        }
        requestBody.hard_copy_existing_tracking_label_url = trackingUrl
      }
    }
    
    this.props.updateHardCopyDate(requestBody)
  }

  handleDatePickerChange = (name) => {
    if (name === 'hard_copy_receive_date') {
      // handle to reset the coverage_period_end
      // if the input change by the customer
      const { form } = this.props
      form.resetFields(['hard_copy_sent_date'])
    }
  }

  handleSelectChange = (name, value) => {
    if (name === 'Order type') {
      this.setState({
        orderType: value,
        trackingDocumentUrl: null
      })
      // Reset tracking number and file upload when order type changes
      if (value !== 'group') {
        const { form } = this.props
        form.resetFields(['hard_copy_existing_tracking_number', 'hard_copy_existing_tracking_label_url'])
      }
    } else {
      this.setState({
        [name]: value
      })
    }
  }

  handleDeliveryTypeChange = (value) => {
    const { form } = this.props
    // Reset order type related fields when delivery type changes
    if (value !== 'shipped-by-pp') {
      this.setState({ 
        orderType: null,
        trackingDocumentUrl: null
      })
      form.resetFields(['hard_copy_order_type', 'hard_copy_existing_tracking_number', 'hard_copy_existing_tracking_label_url'])
    }
  }

  handleFileUpload = (file) => {
    const formData = new FormData()
    const fileName = file.name.split('.')[0].trim()
    const timestamp = Date.parse(new Date())
    
    formData.append('file', file)
    formData.append('path', `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${timestamp}`)
    formData.append('identifier', 'agent')
    
    this.setState({ isUploading: true })
    this.props.uploadPolicyFile({ body: formData })
    
    return false // Prevent default upload behavior
  }

  renderFormItem = ({ name, title, type, disabledDate, placeholder, data, required = true, valuePropName }) => {
    // render the form item date picker
    const { form } = this.props
    const { getFieldDecorator } = form
    let fieldElement = ''
    let message = ''
    
    // Define normFile function for file upload normalization
    const normFile = (e) => {
      if (Array.isArray(e)) {
        return e
      }
      return e && e.fileList
    }
    
    switch (type) {
      case 'text':
        fieldElement = <Input type={type} placeholder={placeholder} />
        message = 'Please enter the policy recipients'
        break
      case 'hard_copy_receive_date':
      case 'hard_copy_sent_date':
        fieldElement = (
          <DatePicker
            disabledDate={(current) => this.handleDisabledDate(current, disabledDate)}
            onChange={() => this.handleDatePickerChange(type)}
            format='DD-MM-YYYY'
          />
        )
        message = `Please select ${title} date`
        break
      case 'select':
        const onChangeHandler = title === 'Delivery Type' 
          ? (value) => {
              this.handleDeliveryTypeChange(value)
              this.handleSelectChange(title, value, data)
            }
          : (value) => this.handleSelectChange(title, value, data)
        fieldElement = (
          <Select
            placeholder={placeholder}
            onChange={onChangeHandler}
          >
            {
              data.map((value) => (
                <Select.Option
                  value={value.code}
                  key={value.code}
                >
                  {value.title}
                </Select.Option>
              ))
            }
          </Select>
        )
        message = title === 'Order type' ? 'Please select order type' : 'Please select the type of delivery'
        break
      case 'textarea':
        fieldElement = <Input.TextArea placeholder={placeholder} />
        break
      case 'upload':
        const { uploadPolicyFileLoading } = this.props
        const isUploading = this.state.isUploading || uploadPolicyFileLoading
        fieldElement = (
          <Upload
            beforeUpload={(file) => {
              this.handleFileUpload(file)
              return false // Prevent default upload
            }}
            accept='.jpg,.jpeg,.png,.pdf,.JPG,.JPEG,.PNG,.PDF'
            multiple={false}
            showUploadList={false}
          >
            <Button disabled={isUploading}>
              <Icon type='upload' /> {isUploading ? 'Uploading...' : 'Click to Upload'}
            </Button>
          </Upload>
        )
        message = 'Please upload a document (JPG, PNG or PDF)'
        break
      default:
        return null
    }
    const decoratorOptions = {
      rules: [
        {
          required,
          message
        }
      ]
    }
    if (valuePropName) {
      decoratorOptions.valuePropName = valuePropName
    }
    if (type === 'upload') {
      // For upload, we'll store the URL directly
      decoratorOptions.valuePropName = 'value'
    }
    return (
      <Form.Item label={title}>
        {
          getFieldDecorator(name, decoratorOptions)(
            fieldElement
          )
        }
      </Form.Item>
    )
  }

  render () {
    const { showModal, onClose, policy = {}, form, updateHardCopyLoader } = this.props
    const isReceiveDate = !get(policy, 'provider_package.pp_generate_hard_copy', false)
    const disabledDate = form.getFieldValue('hard_copy_receive_date') || moment(policy.provider_updated_at)
    const isHardCopySentDate = form.getFieldValue('hard_copy_sent_date')
    const deliveryType = form.getFieldValue('type_of_delivery')
    const orderTypeFromForm = form.getFieldValue('hard_copy_order_type')
    // Use form value if available, otherwise fall back to state (for display purposes)
    const orderType = orderTypeFromForm !== undefined && orderTypeFromForm !== null 
      ? orderTypeFromForm.toLowerCase() 
      : (this.state.orderType ? this.state.orderType.toLowerCase() : null)

    return (
      <Modal
        visible={showModal}
        onCancel={onClose}
        title='Send Hardcopy Policy'
        onOk={this.handleSubmitData}
        okText='Submit'
        confirmLoading={updateHardCopyLoader}
      >
        <HardCopyStatusModalStyle>
          <Form {...this.formItemLayout}>
            {
              isReceiveDate &&
                this.renderFormItem({
                  title: 'Receive Date from Provider',
                  type: 'hard_copy_receive_date',
                  name: 'hard_copy_receive_date',
                  disabledDate
                })
            }
            {
              this.renderFormItem({
                title: 'Date of Policy Delivery',
                type: 'hard_copy_sent_date',
                name: 'hard_copy_sent_date',
                required: !isReceiveDate,
                disabledDate
              })}
            {
              (get(policy, 'hard_copy_details.recipient_name', '') && this.isCourierEnabled)
                ? (
                  <Row type='flex' justify='center' className='margin-10'>
                    <Col className='text-align-right' span={12}>
                      Policy Recipient Name:
                    </Col>
                    <Col span={12}>
                      &nbsp;&nbsp;<b>{get(policy, 'hard_copy_details.recipient_name', '')}</b>
                    </Col>
                  </Row>
                  )
                : this.renderFormItem({
                  title: 'Policy Recipient Name',
                  type: 'text',
                  name: 'hard_copy_recipient',
                  required: !!isHardCopySentDate,
                  placeholder: 'Policy Recipient Name'
                })
            }
            {
              (get(policy, 'hard_copy_details.recipient_mobile', '') && this.isCourierEnabled)
                ? (
                  <Row type='flex' justify='center' className='margin-10'>
                    <Col className='text-align-right' span={12}>
                      Policy Recipient Phone Number:
                    </Col>
                    <Col span={12}>
                      <b>{get(policy, 'hard_copy_details.recipient_mobile', '')}</b>
                    </Col>
                  </Row>
                  )
                : this.renderFormItem({
                  title: 'Policy Recipient Phone Number',
                  type: 'text',
                  name: 'hard_copy_recipient_mobile',
                  required: !!isHardCopySentDate,
                  placeholder: 'Policy Recipient Phone Number'
                })
            }
            {
              this.renderFormItem({
                title: 'Delivery Type',
                type: 'select',
                name: 'type_of_delivery',
                required: !!isHardCopySentDate,
                data: [
                  {
                    title: 'Pickup by Mitra',
                    code: 'pickup-by-agent'
                  },
                  {
                    title: 'Pickup by Marketing',
                    code: 'pickup-by-marketing'
                  },
                  ...(isVNPath()
                    ? []
                    : [{
                        title: 'Shipped by PP',
                        code: 'shipped-by-pp'
                      }]),
                  {
                    title: 'Stored at PP',
                    code: 'stored-at-pp'
                  }
                ],
                placeholder: 'Delivery Type'
              })
            }
            {
              deliveryType === 'shipped-by-pp' &&
              this.renderFormItem({
                title: 'Order type',
                type: 'select',
                name: 'hard_copy_order_type',
                required: !!isHardCopySentDate,
                data: [
                  {
                    title: 'Single',
                    code: 'single'
                  },
                  {
                    title: 'Group',
                    code: 'group'
                  }
                ],
                placeholder: 'Order type'
              })
            }
            {
              deliveryType === 'shipped-by-pp' &&
              orderType === 'group' &&
              this.renderFormItem({
                title: 'Tracking Number',
                type: 'text',
                name: 'hard_copy_existing_tracking_number',
                required: true,
                placeholder: 'Tracking Number'
              })
            }
            {
              deliveryType === 'shipped-by-pp' &&
              orderType === 'group' &&
              this.renderFormItem({
                title: 'Tracking Document',
                type: 'upload',
                name: 'hard_copy_existing_tracking_label_url',
                required: true,
                valuePropName: 'value'
              })
            }
            {
              deliveryType === 'shipped-by-pp' &&
              orderType === 'group' &&
              this.state.trackingDocumentUrl && (
                <Row type='flex' justify='center' className='margin-10'>
                  <Col span={24} style={{ color: 'green', textAlign: 'center' }}>
                    <Icon type='check-circle' /> Document uploaded successfully
                  </Col>
                </Row>
              )
            }
            {
              this.renderFormItem({
                title: 'Remarks',
                name: 'hard_copy_remarks',
                type: 'textarea',
                required: false,
                max: 500, // max 500 chars allowed from the end point
                placeholder: 'Remarks'
              })
            }
          </Form>
          <div className='hard-copy-note'>
            The Status of Sending Print Policy will change to "sent" once you submit this form. Please ensure the status of the Sending Print Policy has been "sent" before submitting the form.
          </div>
        </HardCopyStatusModalStyle>
      </Modal>
    )
  }
}

const WrapperHardCopyStatusModal = Form.create()(HardCopyStatusModal)
export default connect(
  state => ({
    updateHardCopyLoader: state.Loading.UPDATE_HARD_COPY_DATE,
    uploadPolicyFileStatus: state.Policy.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Policy.uploadPolicyFileData,
    uploadPolicyFileLoading: state.Loading.UPLOAD_FILE
  }),
  {
    updateHardCopyDate,
    uploadPolicyFile,
    policyResetReduxState
  }
)(WrapperHardCopyStatusModal)
