import React, { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { Modal, Row, Input, Col, Upload, Button, Icon, message, Form } from 'antd'
import { EditPolicyCertStyle } from './index.style'
import policyActions from '../../../../../../redux/policy/actions'
import CircularLoader from '../../../../../../components/CircularLoader'
import { get, isEmpty, size } from 'lodash'
import ModalImage from 'react-modal-image'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import { DUMMY_FILE_BOX } from '../../../constants'

const { uploadUpdatePolicyNumberFile, resetReduxState, uploadPolicyFile, uploadGenericPolicyFile } = policyActions

class EditPolicyCertNumberModal extends Component {
  static propTypes = {
    isShowModal: PropTypes.bool,
    isPolicyNumberEditable: PropTypes.bool,
    isPolicyCertificateEditable: PropTypes.bool,
    isSpecialNotes: PropTypes.bool,
    isCoverNoteFlowActive: PropTypes.bool,
    isOnlyPolicyCertificateUpload: PropTypes.bool,
    extraDocumentUploadCount: PropTypes.number,
    applicationNo: PropTypes.string,
    childInsurance: PropTypes.array,
    onSubmit: PropTypes.func,
    onCancel: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      extraDocumentUploadCount: props.extraDocumentUploadCount || 1,
      policyNumber: '',
      policyCertificate: '',
      extraDocuments: {},
      premiumDocs: [],
      premiumDocUploadCount: 1,
      loaderMap: {},
      currentExtraFileUploadName: '',
      errorField: ''
    }
    this.multiSelectCallCount = 0
    this.fileUploadToServerCount = 0
    this.filesCount = 0
    this.premiumNoteFilesCount = 0
    this.premiumDocUploadTracker = 0
    this.multiSelectFilesMap = {}
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { uploadPolicyFileData, uploadPolicyFileStatus, resetReduxState } = nextProps
    const { currentExtraFileUploadName } = this.state
    if (uploadPolicyFileStatus === 'success') {
      if (this.premiumDocUploadTracker > 0) {
        this.premiumDocUploadTracker -= 1
        this.setState((prevState) => {
          return {
            premiumDocs: [
              ...prevState.premiumDocs,
              {
                url: uploadPolicyFileData.url,
                name: uploadPolicyFileData.fileName
              }
            ]
          }
        })
      } else if (!isEmpty(this.currentChildInsurance) && !currentExtraFileUploadName) {
        this.setState(prevState => {
          const obj = {}
          if (this.commissionNoteUrl) {
            obj.commissionNoteUrl = uploadPolicyFileData.url
            this.commissionNoteUrl = false
          } else {
            obj.policyCertificate = uploadPolicyFileData.url
          }
          return ({
            [this.currentChildInsurance.reference_id]: {
              ...prevState[this.currentChildInsurance.reference_id],
              ...obj,
              errorField: ''
            }
          })
        })
      } else if (this.multiSelectFilesMap[uploadPolicyFileData.fileName]) {
        // const extraDocument = { id: extraDocumentUploadCount, name: currentExtraFileUploadName, url: uploadPolicyFileData.url }
        // fileName is send as extra param to api call so we are getting this
        const extraDocument = {
          ...(this.multiSelectFilesMap[uploadPolicyFileData.fileName]),
          url: uploadPolicyFileData.url
        }
        delete this.multiSelectFilesMap[uploadPolicyFileData.fileName]
        this.setState(prevState => {
          const { loaderMap } = prevState
          delete loaderMap[uploadPolicyFileData.fileName]
          return {
            loaderMap,
            extraDocuments: {
              ...prevState.extraDocuments,
              [uploadPolicyFileData.fileName]: extraDocument
            }
          }
        })
      } else {
        this.setState(() => {
          const obj = {}
          if (this.commissionNoteUrl) {
            obj.commissionNoteUrl = uploadPolicyFileData.url
            this.commissionNoteUrl = false
          } else {
            obj.policyCertificate = uploadPolicyFileData.url
          }
          return {
            ...obj,
            errorField: ''
          }
        })
      }

      resetReduxState(['uploadPolicyFileStatus'])
    }
  }

  customRequest = ({ file }, insurance) => {
    this.currentChildInsurance = insurance
    const formData = new FormData()
    // we are sending this values for storage identification
    // path --> `insurance-policy-certificate-control-panel/{app_no+timestamp}`
    // identifier --> agent
    let fileSize = file.size // size in b
    fileSize = fileSize / 1048576 // size in mb
    if (fileSize >= 11) {
      message.error('Sorry, We are not allowing to upload file size more than 10MB')
      return
    }
    const fileExt = file.name && file.name.split('.').pop()
    let fileName = `${this.props.applicationNo}_${Date.now()}_${file.name}`
    if (fileExt) {
      fileName = `${this.props.applicationNo}_${Date.now()}.${fileExt}`
    }

    formData.append('file', file, fileName)
    formData.append('path', `insurance-policy-certificate-control-panel/${fileName}`)
    formData.append('identifier', 'agent')
    this.props.uploadPolicyFile({ body: formData, fileName })
  }

  extraDetailDocumentUpload = (file) => {
    const { extraDocumentUploadCount } = this.state
    // .zip extension allow .xlsx and .xls file adding extra check and throw error
    if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
      message.error('Sorry, We are not allowing to upload .xls or .xlsx files')
      return
    }
    if (extraDocumentUploadCount > 5) {
      message.error('cannot upload more than 5 document\'s')
      return
    }
    const formData = new FormData()
    const fileName = `${Date.parse(new Date())}_${file.name}`
    formData.append('file', file, `${fileName}`)
    formData.append('path', `insurance-policy-certificate-control-panel/${fileName}`)
    formData.append('identifier', 'agent')
    this.props.uploadGenericPolicyFile({ body: formData, fileName })
    if (file) {
      this.fileUploadToServerCount += 1
      this.multiSelectFilesMap = {
        ...this.multiSelectFilesMap,
        [fileName]: {
          id: this.fileUploadToServerCount,
          name: fileName
        }
      }
      this.setState({
        loaderMap: {
          [fileName]: true
        },
        currentExtraFileUploadName: fileName
      })
    }
  }

  renderExtraDocumentImages = (item) => {
    const ext = getUrlExtension(item.url)
    if (item && (item.name.endsWith('.zip') || item.name.endsWith('.rar'))) {
      return (
        <div width='200' height='150'>
          <img src={DUMMY_FILE_BOX} alt='rar_zip_image_view' />
        </div>
      )
    } else if (item && item.name.endsWith('.docx')) {
      const url = item.url
      return (
        <iframe title='GView' width='200' height='150' src={`https://docs.google.com/gview?url=${url}&embedded=true`} />
      )
    } else if (['png', 'jpg', 'jpeg'].includes(ext)) {
      return (
        <ModalImage
          className='object-image'
          small={item.url}
          large={item.url}
        />
      )
    } else {
      return (
        <object
          key={item.id}
          data={item.url}
          width='200'
          height='150'
          aria-label='Extra Document'
        />
      )
    }
  }

  handlePolicyNumber = (e, insurance) => {
    this.currentChildInsurance = insurance
    // here handle the policy number field
    // update the error field value if its policyNumber
    const { errorField } = this.state
    const inputValue = e.target.value
    if (!isEmpty(this.currentChildInsurance)) {
      this.setState(prevState => ({
        [insurance.reference_id]: {
          ...prevState[insurance.reference_id],
          policyNumber: inputValue,
          errorField: errorField === 'policyNumber' ? '' : errorField
        }
      }))
    } else {
      this.setState({
        policyNumber: e.target.value,
        errorField: errorField === 'policyNumber' ? '' : errorField
      })
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleSubmitDetail = async (e) => {
    // this is check if both needed or not if only one then
    // change or disable the submit
    e.preventDefault()
    const {
      isPolicyNumberEditable, isPolicyCertificateEditable,
      childInsurance = [], form, dataProfile
    } = this.props
    const valid = await this.validateForm()
    if (!valid) return
    const formValues = {
      ...form.getFieldsValue()
    }
    const specialNotes = {}
    if (formValues.providerNotes) {
      specialNotes.special_notes = {
        provider: {
          name: dataProfile.name,
          email: dataProfile.email,
          remark: formValues.providerNotes
        }
      }
    }
    const { policyNumber, policyCertificate, extraDocuments, commissionNoteUrl, premiumDocs } = this.state
    if (size(childInsurance)) {
      // if child insurance not empty then
      // add checks on basis of object
      const insuranceDocObj = {}
      const errorObj = {}
      const policyNumberMap = {}
      childInsurance.forEach((insurance, index) => {
        const obj = this.state[insurance.reference_id] || {}
        const docObj = {}
        const docError = {}
        if (isPolicyNumberEditable) {
          const policyNumber = formValues[`policyNumber_${index}`]
          if (policyNumber && !policyNumberMap[policyNumber]) {
            policyNumberMap[policyNumber] = true
            docObj.insurance_policy_no = policyNumber
          } else {
            // have to handle the error state
            if (policyNumberMap[policyNumber]) {
              message.error('Please make sure that the policy number must be unique!')
            }
            docError.policyNumberError = 'policyNumber'
          }
        }

        if (isPolicyCertificateEditable) {
          if (obj.policyCertificate) {
            docObj.document_url = obj.policyCertificate
          } else {
            // have to handle the error state
            docError.policyCertificateError = 'policyCertificate'
          }
        }
        if (obj.commissionNoteUrl) {
          docObj.commission_note_url = obj.commissionNoteUrl
        }
        insuranceDocObj[insurance.reference_id] = {
          ...docObj
        }
        if (!isEmpty(docError)) {
          errorObj[insurance.reference_id] = {
            ...docError
          }
        }
      })
      if (isEmpty(errorObj)) {
        // here creating the request body for the activate policy
        const req = {
          ...specialNotes,
          child_insurance_details: {
            ...insuranceDocObj
          },
          extra_document_urls: extraDocuments,
          premium_note_urls: premiumDocs
        }
        if (premiumDocs?.length > 0) {
          req.premium_note_urls = premiumDocs
        }
        this.props.onSubmit(req)
      }
      return
    }
    if (isPolicyCertificateEditable && !policyCertificate) {
      message.error('Please upload policy certificate')
      this.setState({
        errorField: 'policyNumber'
      })
      return
    }

    if (isPolicyNumberEditable && !policyNumber) {
      message.error('Please enter policy number')
      this.setState({
        errorField: 'policyCertificate'
      })
      return
    }
    // if all correct then update this field
    if (this.state.errorField) {
      this.setState({
        errorField: ''
      })
    }
    // this is the data send in policy activation url
    // if policy number and
    const req = {
      ...specialNotes,
      commission_note_url: commissionNoteUrl,
      insurance_policy_no: policyNumber,
      document_url: policyCertificate,
      extra_document_urls: extraDocuments
    }
    if (premiumDocs?.length > 0) {
      req.premium_note_urls = premiumDocs
    }
    this.props.onSubmit(req)
  }

  getFooterNode = () => {
    return (
      <Row type='flex' justify='space-between' align='center'>
        <Col />
        <Col>
          <Button onClick={this.props.onCancel}>Cancel</Button>
          <Button
            type='primary'
            onClick={this.handleSubmitDetail}
          >
            Submit
          </Button>
        </Col>
      </Row>
    )
  }

  renderTheUploadInputContainer = (policyCertificate, commissionNoteUrl, insurance = {}, index = 0) => {
    const {
      isPolicyNumberEditable, isPolicyCertificateEditable, form,
      isCoverNoteFlowActive, isOnlyPolicyCertificateUpload
    } = this.props
    const { getFieldDecorator } = form
    const insuredElementName = (
      insurance.insurance_for
        ? (
          <>
            &nbsp;
            {insurance.insurance_for}
          </>
          )
        : ''
    )
    return (
      <>
        {
          (isPolicyCertificateEditable || (isCoverNoteFlowActive && isOnlyPolicyCertificateUpload)) && (
            <Row>
              <Col className='edit-policy-title'>
                {(isCoverNoteFlowActive && !isOnlyPolicyCertificateUpload)
                  ? `Cover Note ${insuredElementName}`
                  : <span>Policy Certificate{insuredElementName} (Downloadable by agent)</span>}
                <span className='required-star'>*</span>
              </Col>
              <Col>
                {
                  policyCertificate
                    ? (
                      <object
                        type='application/pdf'
                        data={policyCertificate}
                        width='200'
                        height='150'
                        aria-label='PDF'
                      />
                      )
                    : (
                      <Form.Item>
                        {getFieldDecorator(`policyCertificate_${index}`, {
                          rules: [
                            {
                              required: true,
                              message: 'Please upload policy certificate!'
                            }
                          ]
                        })(
                          <Upload
                            multiple={false}
                            showUploadList={false}
                            accept='.pdf'
                            customRequest={fileData => this.customRequest(fileData, insurance)}
                          >
                            <Button>
                              <Icon type='upload' />
                              Click to upload
                            </Button>
                          </Upload>
                        )}
                      </Form.Item>
                      )
                }
              </Col>
            </Row>
          )
        }
        {
          isPolicyNumberEditable && (
            <Row className='policy-number'>
              <Col className='edit-policy-title'>
                Policy Number{insuredElementName} <span className='required-star'>*</span>
              </Col>
              <Col>
                <Form.Item>
                  {getFieldDecorator(`policyNumber_${index}`, {
                    rules: [
                      {
                        required: true,
                        message: 'Please enter policy number!'
                      }
                    ]
                  })(
                    <Input onChange={(e) => this.handlePolicyNumber(e, insurance)} />
                  )}
                </Form.Item>
              </Col>
            </Row>
          )
        }
        {this.renderUploadCommissionNote(insurance.insurance_for, insurance, commissionNoteUrl)}
        {(process.env.REACT_APP_IS_INVOICE_ENABLED === 'true') && this.renderUploadPremiumNote(insurance.insurance_for, insurance)}
      </>
    )
  }

  renderUploadCommissionNote = (insuranceName, insurance, commissionNoteUrl) => {
    return (
      <>
        <Col className='edit-policy-title'>
          Commission/Credit Note {insuranceName}
          &nbsp;(Visible to PasarPolis internal team only)
        </Col>
        <Col>
          {
            commissionNoteUrl
              ? (
                <div className='img-container'>
                  {
                    this.renderExtraDocumentImages({
                      name: 'Commission Note',
                      url: commissionNoteUrl,
                      id: `Commission Note ${insuranceName}`
                    })
                  }
                  <br />
                </div>
                )
              : (
                <Form.Item>
                  <Upload
                    showUploadList={false}
                    accept='.pdf,.png,.jpg,.jpeg'
                    customRequest={(fileData) => this.handleCommissionNoteUrl(fileData, insurance)}
                  >
                    <Button>
                      <Icon type='upload' />
                      Click to upload
                    </Button>
                  </Upload>
                </Form.Item>
                )
          }
        </Col>
      </>
    )
  }

  renderUploadPremiumNote = (insuranceName, insurance) => {
    const { premiumDocUploadCount, premiumDocs } = this.state
    return (
      <>
        <Col className='edit-policy-title'>
          Premium Note (max 5 files: PDF/Images)
        </Col>
        {
          (premiumDocUploadCount < 5) &&
            <Col>
              <Form.Item>
                <Button className='upload-button-wrapper'>
                  <Icon type='upload' />
                  <input
                    type='file'
                    id='premiumDocumentsFiles'
                    name='premiumDocumentsFiles'
                    accept='.pdf,.png,.jpg,.jpeg'
                    multiple
                    onChange={() => this.handleOnChangePremiumNoteFiles(insurance)}
                  />
                &nbsp;&nbsp;Click to upload
                </Button>
              </Form.Item>
            </Col>
        }
        {
          (premiumDocs) &&
          (premiumDocs.map((doc, i) => (
            <div className='img-container' key={i}>
              {
                this.renderExtraDocumentImages({
                  name: doc.name,
                  url: doc.url,
                  id: `Premium Note ${insuranceName} ${i}`
                })
              }
            </div>
          )
          ))
        }
      </>
    )
  }

  handleOnChangePremiumNoteFiles = (insurance) => {
    const fileInput = document.getElementById('premiumDocumentsFiles')
    if ('files' in fileInput) {
      const fileList = fileInput.files
      if (((fileList && fileList.length > 5) ||
        (this.premiumNoteFilesCount && (this.premiumNoteFilesCount + fileList.length > 5))) && !this.showMaxFileUploadError
      ) {
        // check if selected files is less than max allowed files
        this.showMaxFileUploadError = true
        setTimeout(() => {
          this.showMaxFileUploadError = false
        }, 50)
        fileInput.value = ''
        message.error('cannot upload more than 5 document\'s')
        return false
      }

      this.premiumNoteFilesCount += fileList.length
      if (this.premiumNoteFilesCount === 5) {
        this.setState({
          premiumDocUploadCount: this.premiumNoteFilesCount
        })
      }
      this.premiumDocUploadTracker = fileList.length
      for (const file of fileList) {
        this.customRequest({ file }, insurance)
      }
      fileInput.value = ''
    }
  }

  handleCommissionNoteUrl = (fileData, insurance) => {
    this.commissionNoteUrl = true
    this.customRequest(fileData, insurance)
  }

  handleOnChangeMultipleFiles = () => {
    const fileInput = document.getElementById('otherDocumentsFiles')
    if ('files' in fileInput) {
      const fileList = fileInput.files
      if (((fileList && fileList.length > 5) ||
        (this.filesCount && (this.filesCount + fileList.length > 5))) && !this.showMaxFileUploadError
      ) {
        // check if selected files is less than max allowed files
        this.showMaxFileUploadError = true
        setTimeout(() => {
          this.showMaxFileUploadError = false
        }, 50)
        fileInput.value = ''
        message.error('cannot upload more than 5 document\'s')
        return false
      }

      this.filesCount += fileList.length
      if (this.filesCount === 5) {
        this.setState({
          extraDocumentUploadCount: this.filesCount
        })
      }
      for (const file of fileList) {
        this.extraDetailDocumentUpload(file)
      }
      fileInput.value = ''
    }
  }

  renderExtraDetailDocumentUpload = () => {
    const { extraDocumentUploadCount, extraDocuments } = this.state
    return (
      <>
        {(extraDocumentUploadCount < 5) &&
          <>
            <Col className='edit-policy-title'>
              Other document like clause, premium note, etc.<br />
              Downloadable by agent (max 5 files : PDF,MS-WORD,ZIP,RAR)
            </Col>
            <Col>
              <Form.Item>
                <Button className='upload-button-wrapper'>
                  <Icon type='upload' />
                  <input
                    type='file'
                    id='otherDocumentsFiles'
                    name='otherDocumentsFiles'
                    multiple
                    onChange={this.handleOnChangeMultipleFiles}
                  />
                  &nbsp;&nbsp;Click to upload
                </Button>
              </Form.Item>
            </Col>
          </>}
        {
          (extraDocuments) &&
          (Object.entries(extraDocuments).map((item) => this.renderExtraDocumentImages(item[1])))
        }
      </>
    )
  }

  renderProviderNotes = () => {
    const { getFieldDecorator } = this.props.form
    return (
      <Row className='policy-number'>
        <Col className='edit-policy-title'>
          Note from Provider (Max 1000 characters)
        </Col>
        <Col>
          <Form.Item>
            {getFieldDecorator('providerNotes', {
              rules: [
                {
                  required: false,
                  message: 'Please enter notes...'
                }
              ]
            })(
              <Input.TextArea />
            )}
          </Form.Item>
        </Col>
      </Row>
    )
  }

  render () {
    const {
      isShowModal, onCancel, uploadPolicyFileLoading,
      childInsurance = [], isSpecialNotes,
      isCoverNoteFlowActive, isOnlyPolicyCertificateUpload
    } = this.props
    const { policyCertificate, loaderMap, commissionNoteUrl } = this.state
    return (
      <Modal
        title='Activate Policy'
        visible={isShowModal}
        onCancel={onCancel}
        okText='Submit'
        footer={this.getFooterNode()}
      >
        <CircularLoader isSpining={uploadPolicyFileLoading || !isEmpty(loaderMap)}>
          <EditPolicyCertStyle>
            <Form>
              {
                size(childInsurance)
                  ? (
                      childInsurance.map((insurance, index) => {
                        return this.renderTheUploadInputContainer(
                          get(this.state, `${insurance.reference_id}[policyCertificate]`, ''),
                          get(this.state, `${insurance.reference_id}[commissionNoteUrl]`, ''),
                          insurance,
                          index
                        )
                      })
                    )
                  : this.renderTheUploadInputContainer(policyCertificate, commissionNoteUrl, undefined, 0)
              }
              {this.renderExtraDetailDocumentUpload()}
              {
                !isSpecialNotes && this.renderProviderNotes()
              }
              <div className='btm-note'>
                Policy will active when you submit the form.<br />
                The customer will receive a notification email and document as well as a {(isCoverNoteFlowActive && !isOnlyPolicyCertificateUpload) ? 'Cover Note' : 'Policy Certificate'}.
                The Commission/Credit Note is not attached to the customer email notification and cannot be downloaded by the agent.
              </div>
            </Form>
          </EditPolicyCertStyle>
        </CircularLoader>
      </Modal>
    )
  }
}

const wrapperEditPolicyNumber = Form.create()(EditPolicyCertNumberModal)
export default connect(
  state => ({
    uploadPolicyFileLoading: state.Loading.UPLOAD_FILE,
    dataProfile: state.Auth.profile,
    uploadUpdatePolicyNumberFileError: state.Error.UPLOAD_FILE,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData
  }),
  {
    uploadUpdatePolicyNumberFile,
    uploadPolicyFile,
    uploadGenericPolicyFile,
    resetReduxState
  }
)(wrapperEditPolicyNumber)
