import React, { useState } from 'react'
import PropTypes from 'prop-types'
import { Row, Col, Button, Modal, Input } from 'antd'
import { ModalWrapper } from '../../policy.style'
import { capitalizeFirstLetter } from '../../../../../../helpers/utility'
import DynamicForm from './DynamicForm'

const EditFieldModal = ({
  visible,
  title,
  editableFieldKey,
  editableFieldValue,
  editableFieldUserInput,
  editableFieldUserInputRemarks,
  fieldError,
  regionCode,
  onClose,
  onChangeInput,
  onChangeRemarks,
  onSubmit,
  vehicleValidYears
}) => {
  const [isFieldValid, setIsFieldValid] = useState(true)
  const disabled = !editableFieldUserInput || !editableFieldUserInputRemarks || !isFieldValid
  return (
    <Modal
      title={title || `Edit ${capitalizeFirstLetter(editableFieldKey)}`}
      visible={visible}
      onCancel={onClose}
      footer={null}
    >
      <ModalWrapper>
        <Row gutter={40}>
          <Col span={24}>
            <span>
              Update the field value and provide a remarks for the change
            </span>
          </Col>
          <Col span={24} className='label'>
            <label className='text-bold'>Current Value</label>
          </Col>
          <Col span={24}>
            <p className='editable-modal-value'>{editableFieldValue}</p>
          </Col>
          <Col span={24} className='col-gap'>
            <label className='text-bold'>
              New Value <span className='required'>*</span>
            </label>
          </Col>
          <Col span={24}>
            <DynamicForm
              editableFieldKey={editableFieldKey}
              editableFieldValue={editableFieldValue}
              editableFieldUserInput={editableFieldUserInput}
              onChangeInput={onChangeInput}
              onValidate={setIsFieldValid}
              regionCode={regionCode}
              vehicleValidYears={vehicleValidYears}
            />
            {fieldError && (
              <div style={{ color: '#f5222d', marginTop: 8, fontSize: 12 }}>
                {fieldError}
              </div>
            )}
          </Col>
          <Col span={24} className='col-gap'>
            <label className='text-bold'>
              Remarks <span className='required'>*</span>
            </label>
          </Col>
          <Col span={24}>
            <Input.TextArea
              placeholder='Enter remarks..'
              value={editableFieldUserInputRemarks}
              onChange={e => onChangeRemarks(e.target.value)}
              autoSize={{ minRows: 3, maxRows: 5 }}
              id={`editable-textarea-${editableFieldKey}`}
            />
          </Col>
          <Col span={24} className='col-gap'>
            <div className='footer-actions'>
              <Button className='btn-cancel-modal' onClick={onClose}>
                Cancel
              </Button>
              <Button className='btn-confirm-modal success' disabled={disabled} onClick={onSubmit}>
                Save
              </Button>
            </div>
          </Col>
        </Row>
      </ModalWrapper>
    </Modal>
  )
}

EditFieldModal.propTypes = {
  visible: PropTypes.bool,
  title: PropTypes.string,
  editableFieldKey: PropTypes.string,
  editableFieldValue: PropTypes.any,
  editableFieldUserInput: PropTypes.any,
  fieldError: PropTypes.any,
  regionCode: PropTypes.string,
  editableFieldUserInputRemarks: PropTypes.any,
  onClose: PropTypes.func.isRequired,
  onChangeInput: PropTypes.func.isRequired,
  onChangeRemarks: PropTypes.func.isRequired,
  onSubmit: PropTypes.func.isRequired
}

EditFieldModal.defaultProps = {
  visible: false,
  title: '',
  editableFieldKey: '',
  editableFieldValue: '',
  editableFieldUserInput: '',
  regionCode: '',
  fieldError: '',
  editableFieldUserInputRemarks: ''
}

export default EditFieldModal
