import { Icon, Input, Modal, Row, Col } from 'antd'
import { PolicyActiveNotesStyle } from './index.style'
import { useCallback, useRef } from 'react'
import { COLORS } from '../../../../../../constants/colors'

function PolicyActivateNotes ({ show, onClose, onOk, isLoader }) {
  const that = useRef()

  const handleOnChange = useCallback((e) => {
    that.current = e.currentTarget.value
  }, [])

  const handleOnOk = useCallback(() => {
    onOk(that.current)
  }, [onOk])

  return (
    <Modal
      title='Aktivasi Polis'
      visible={show}
      onCancel={onClose}
      okText='Yes'
      onOk={handleOnOk}
      cancelText='No'
      okButtonProps={{
        loading: isLoader
      }}
    >
      <PolicyActiveNotesStyle>
        <Row type='flex' align='middle'>
          <Col className='icon-center'>
            <Icon
              fill={COLORS.orange}
              type='info-circle'
              className='info-orange'
              theme='twoTone'
              width='1.2em'
              height='1.2em'
              twoToneColor={COLORS.orange}
            />
          </Col>
          <Col className='warning-info'>
            Are you sure to issue the policy?
          </Col>
        </Row>
        <div className='notes-label'>Note from Provider (Max 1000 characters)</div>
        <Input.TextArea onChange={handleOnChange} />
        <div className='policy-info-notes'>
          Policy will active immediately when you click button Yes.<br />
          Customers will receive notification emails and policy documents.
        </div>
      </PolicyActiveNotesStyle>
    </Modal>
  )
}

export default PolicyActivateNotes
