import { Table } from 'antd'
import PropTypes from 'prop-types'
import { useMemo } from 'react'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'

const columns = [
  {
    title: 'File Name',
    dataIndex: 'name',
    key: 'name',
    render: (value, record) => {
      const urlToTitle = record.url ? record.url.split('/').pop() : ''
      return value || urlToTitle
    }
  },
  {
    title: 'File Type',
    dataIndex: 'file_type',
    key: 'file_type',
    render: (value) => {
      return value || '-'
    }
  },
  {
    title: 'File',
    dataIndex: 'url',
    key: 'url',
    render: (value) => {
      return value ? <a href={value} target='_blank' rel='noopener noreferrer'>View File</a> : '_'
    }
  }
]
const PolicyOtherDocs = ({ policyDetails = {} }) => {
  const extraDocuments = useMemo(() => {
    const extraDocsCoverNoteFlow = Object.values(policyDetails?.extra_document_urls || {})
    const extraDocs = Object.values(policyDetails?.extra_document_urls_cover_note_flow || {})
    let extraDocuments = [
      ...extraDocs,
      ...extraDocsCoverNoteFlow
    ]
    if (policyDetails.commission_note_url) {
      extraDocuments = [
        ...extraDocuments,
        {
          id: 'commission_note_url',
          name: 'Commission/Credit Note',
          url: policyDetails.commission_note_url
        }
      ]
    }
    return extraDocuments
  }, [policyDetails])

  return (
    extraDocuments.length > 0 && (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>Other Documents</h3>
          <Table
            pagination={{
              pageSize: 100
            }}
            rowKey={data => data.name}
            columns={columns}
            bordered
            dataSource={extraDocuments}
          />
        </div>
      </LayoutContentStyle>
    )
  )
}

PolicyOtherDocs.propTypes = {
  policyDetails: PropTypes.object
}
export default PolicyOtherDocs
