import { useCallback } from 'react'
import { Row, Col, Icon, Button } from 'antd'
import ModalImage from 'react-modal-image'
import { get } from 'lodash'
import getUrlExtension from '../../../../../../../helpers/getExtensionUrl'

function Attachments (props) {
  const {
    renderFormItems, endorsmentFile, renderImgAndPdf,
    onRemoveEndorsmentFile, isPreview, reviewData = {},
    isDetail, proofImages = []
  } = props

  const renderAttachments = useCallback(() => {
    return (
      <div>
        <Row type='flex'>
          <div className='margin-right-20'>
            {
            endorsmentFile
              ? (
                <>
                  <div className='form-field-title'>Endorsement Document</div>
                  <div className='documents-container'>
                    {renderImgAndPdf(endorsmentFile)}
                    <div className='cross-mark' onClick={onRemoveEndorsmentFile}>
                      <Icon type='cross' />
                    </div>
                  </div>
                </>
                )
              : renderFormItems({
                name: 'endorsement_file',
                title: 'Endorsement File(s)',
                placeholder: 'Upload Documents',
                type: 'upload',
                required: true,
                disabled: false,
                accept: 'image/*,.pdf'
              })
          }
          </div>
        </Row>
        {
          renderFormItems({
            name: 'remarks',
            title: 'Remarks',
            placeholder: '',
            type: 'textarea',
            required: true,
            disabled: false
          })
        }
      </div>
    )
  }, [
    renderFormItems, renderImgAndPdf,
    onRemoveEndorsmentFile, endorsmentFile
  ])

  const downloadPdf = useCallback((fileUrl) => {
    window.open(fileUrl)
  }, [])

  const renderImageObject = useCallback((fileUrl) => {
    const fileExt = getUrlExtension(fileUrl)
    if (fileExt === 'pdf') {
      return (
        <div className='documents-container'>
          <div className='pdf-container'>
            <object
              type='application/pdf'
              data={fileUrl}
              width='150'
              height='150'
              aria-label='PDF'
            />
            <div className='view-pdf-btn-container'>
              <Button
                onClick={() => downloadPdf(fileUrl)}
              >
                View Pdf
              </Button>
            </div>
          </div>
        </div>
      )
    } else {
      return (
        <div className='documents-container'>
          <ModalImage
            className='policy-img'
            small={fileUrl}
            large={fileUrl}
            name=''
            imageBackgroundColor='transparent'
          />
        </div>
      )
    }
  }, [downloadPdf])

  const renderPreviewAttachments = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        <Col span={4} className='field-margin'>
          <h3>
            Endorsement File
          </h3>
          <div>
            {renderImageObject(get(reviewData, 'endorsement_file_url'))}
          </div>
        </Col>
        {
          (proofImages?.length > 0) &&
            <Col>
              <h3 className='text-center'>
                Proofs Of Payment
              </h3>
              <Row>
                {
              proofImages.map((proof, i) => (
                <Col span={4} className='field-margin' key={i}>
                  {renderImageObject(proof)}
                </Col>
              ))
            }
              </Row>
            </Col>
        }
        <Col span={24} className='field-margin'>
          <h3>
            Remark
          </h3>
          <div>
            {get(reviewData, 'remarks', '')}
          </div>
        </Col>
      </Row>
    )
  }, [reviewData, renderImageObject, proofImages])

  return (
    <div>
      {
        isPreview || isDetail
          ? <h2>Attachments</h2>
          : <h3>Attachments</h3>
      }

      {
        isPreview || isDetail
          ? renderPreviewAttachments()
          : renderAttachments()
      }
    </div>
  )
}

export default Attachments
