import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { Button, Form, Popconfirm, Row, Radio, Icon } from 'antd'
import { isEmpty, get } from 'lodash'
import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { checkIsLvAgent } from 'opsModule/helpers'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent.style'
import { showNotification } from '../../../../../../components/ShowNotification'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import UploadImgPreview from '../../../components/UploadImgPreview'
import { useGetCommissionPoints, useUpdateCommission } from '../../state/hooks/useAgentPolicyState'
import { CommissionEditStyle, SwitchContainer } from './index.style'

function CommissionEdit (props) {
  const {
    policyId,
    commissionApprovalStatus,
    getCommissionApprovalStatus,
    commissionData = {},
    form,
    policyDetails,
    agentScore = {}
  } = props
  const { getFieldValue, getFieldDecorator, validateFields } = form
  const [outgoingCommissionRate, pointsFromProvider] = [
    getFieldValue('outgoing_commission_rate'),
    getFieldValue('points_from_provider')
  ]

  const [errorObj, setErrorObj] = useState({})
  const [binderType, setBinderType] = useState('')
  const [screenshot, setScreenshot] = useState(commissionData.link_for_email_approval || '')
  const [, updateCommissionRequest] = useUpdateCommission()
  const [{ getCommissionsPointsData = {} }, getCommissionPointsRequest] = useGetCommissionPoints()

  const isLVAgent = useMemo(() => checkIsLvAgent(policyDetails?.agent), [policyDetails])
  const isOnline = useMemo(() => policyDetails && policyDetails?.policy_type === 'Online', [policyDetails])
  const isO2O = useMemo(() => policyDetails && policyDetails?.policy_type === 'O2O', [policyDetails])
  const isOffline = useMemo(() => policyDetails && policyDetails?.policy_type === 'Offline', [policyDetails])
  const isAutoDisbursed = useMemo(() => commissionData.commission_disbursement_method === 'auto', [commissionData])

  // Hide upload when agent is LV, policy is Offline and commission status is no-approval-required
  const isUploadHidden = isLVAgent && isOffline && commissionApprovalStatus === 'no-approval-required'

  const productKey = get(policyDetails, 'request.product_key', '')

  const getCommissionPoints = useCallback(() => {
    const payload = {
      agent_type: isLVAgent ? 'LV' : 'NON-LV',
      agent_code: policyDetails?.agent_code || '',
      product_version: isO2O ? 'O2O' : 'offline',
      product_key: policyDetails?.request?.product_key || '',
      package_code: policyDetails?.request?.package
        ? policyDetails?.request?.package || ''
        : policyDetails?.request?.product_key || '',
      provider_code: policyDetails?.request?.provider_code || '',
      medium: (isOnline && 'ONLINE') || // Online -> ONLINE
        ((isO2O || isOffline) && 'OFFLINE'), // O2O & Offline -> OFFLINE
      binder_type: binderType || policyDetails?.request?.binder_type,
      category: policyDetails?.agent?.category || 'RETAIL',
      agentScore
    }
    if (isO2O) {
      payload.policy_ref_id = policyDetails?.reference_id
    }
    if (policyDetails?.agent?.parent_code) {
      payload.parent = policyDetails?.agent?.parent_code
    }
    getCommissionPointsRequest({
      body: payload
    })
  }, [policyDetails, isO2O, binderType, getCommissionPointsRequest, isLVAgent, agentScore])

  const isAllowEditPoint = isLVAgent && ['car-protection', 'property-protection'].includes(productKey)

  // Disabled when commission is NOT in edit state, agent is LV, and product is not car/property protection
  const isDisableFields =
    (commissionApprovalStatus !== 'pending-commission-points-edit')

  const [{ UPDATE_COMMISSION_ERROR, updateCommissionStatus }, dispatchError] =
    useErrorContextValue()

  // initialize binderType on mount / when policyDetails or disbursement mode changes
  // do not override user's selection once they change it
  const userChangedBinderTypeRef = React.useRef(false)
  useEffect(() => {
    if (isO2O && isAutoDisbursed) {
      // For auto disbursement, hardcode binderType to 'inside'
      setBinderType('inside')
      userChangedBinderTypeRef.current = false
      return
    }

    // If user manually changed the binderType, don't override it
    if (userChangedBinderTypeRef.current) {
      return
    }

    if (policyDetails?.request?.binder_type) {
      // Initialize from policyDetails when available
      setBinderType(policyDetails.request.binder_type)
    } else {
      // Default value
      setBinderType('outside')
    }
    // intentionally depend only on policy details and disbursement mode
    // so we don't override user's manual selection
  }, [isO2O, isAutoDisbursed, policyDetails?.request?.binder_type])

  useEffect(() => {
    if (binderType && policyDetails && Object.keys(policyDetails)?.length > 0) {
      getCommissionPoints()
    }
  }, [binderType, policyDetails, getCommissionPoints])

  useEffect(() => {
    if (updateCommissionStatus === 'success') {
      showNotification('success', 'Commission successfully Updated')
      getCommissionApprovalStatus()
      dispatchError(
        resetError({
          updateCommissionStatus: ''
        })
      )
    } else if (UPDATE_COMMISSION_ERROR && updateCommissionStatus) {
      showNotification('error', updateCommissionStatus)
      dispatchError(
        resetError({
          updateCommissionStatus: ''
        })
      )
    }
  }, [
    updateCommissionStatus,
    UPDATE_COMMISSION_ERROR,
    dispatchError,
    getCommissionApprovalStatus
  ])

  useEffect(() => {
    if (
      commissionData.link_for_email_approval &&
      screenshot &&
      screenshot !== commissionData.link_for_email_approval
    ) {
      setScreenshot(commissionData.link_for_email_approval)
    }
  }, [commissionData.link_for_email_approval, screenshot])

  const renderFormItems = useCallback(
    (item) => {
      // wrapping utitily function with class function to pass common parameters
      return renderFormItemsUtil({
        ...item,
        getFieldDecorator,
        getFieldValue
      })
    },
    [getFieldDecorator, getFieldValue]
  )

  const renderForm = useCallback(
    (policyDetails, getCommissionsPointsData) => {
      const formData = [
        {
          name: 'incoming_commission_rate',
          title: 'Incoming Commission',
          type: 'number',
          min: 0,
          defaultValue: getCommissionsPointsData?.incoming_commission_rate ?? 0,
          disabled: true,
          className: 'w-40'
        },
        {
          name: 'recruitment_bonus',
          title: 'Rekrutmen Bonus',
          type: 'number',
          min: 0,
          defaultValue: getCommissionsPointsData?.recruitment_bonus ?? 0,
          disabled: true,
          className: 'w-40',
          hidden: !isLVAgent
        },
        {
          name: 'outgoing_commission_rate',
          title: 'Outgoing Commission',
          type: 'number',
          min: 0,
          defaultValue: commissionData?.commission_rate ?? 0,
          disabled: true,
          className: 'w-40'
        },
        {
          name: 'overriding_bonus',
          title: 'Overriding Bonus',
          type: 'number',
          min: 0,
          defaultValue: getCommissionsPointsData?.overriding_bonus ?? 0,
          disabled: true,
          className: 'w-40',
          hidden: !isLVAgent
        },
        {
          name: 'extra_points_by_pp',
          title: 'Incoming Points',
          type: 'number',
          min: 0,
          defaultValue:
            commissionData?.extra_points_by_pp ??
            getCommissionsPointsData?.incoming_points_rate ?? 0,
          disabled: isDisableFields && !isAllowEditPoint,
          className: 'w-40'
        },
        {
          name: 'royalty_bonus',
          title: 'Royalty Bonus',
          type: 'number',
          min: 0,
          defaultValue: getCommissionsPointsData?.royalty_bonus ?? 0,
          disabled: true,
          className: 'w-40',
          hidden: !isLVAgent
        },
        {
          name: 'points_from_provider',
          title: 'Outgoing Points',
          type: 'number',
          min: 0,
          defaultValue:
            commissionData?.points_rate ?? 0,
          disabled: isDisableFields && !isAllowEditPoint,
          className: 'w-40'
        },
        {
          name: 'founder_bonus',
          title: 'Founders Bonus',
          type: 'number',
          min: 0,
          defaultValue: getCommissionsPointsData?.founder_bonus ?? 0,
          disabled: true,
          className: 'w-40',
          hidden: !isLVAgent
        }
      ]
      return formData.map((item, index) => {
        const el = renderFormItems(item)
        return <React.Fragment key={item.name || index}>{el}</React.Fragment>
      })
    },
    [renderFormItems, commissionData, isDisableFields,isLVAgent, isAllowEditPoint]
  )

  const handleSaveNewUploadImg = useCallback((file, fileType) => {
    switch (fileType) {
      case 'screenshot':
        setErrorObj({
          screenshot: ''
        })
        setScreenshot(file)
        break
      default:
    }
  }, [])

  const handleRemoveImg = useCallback((fileType) => {
    switch (fileType) {
      case 'screenshot':
        setScreenshot('')
        break
      default:
    }
  }, [])

  const handleChangeBinderData = (e) => {
    userChangedBinderTypeRef.current = true
    setBinderType(e.target.value)
  }

  const handleSubmit = useCallback(
    (e) => {
      e.preventDefault()
      validateFields(async (err, values) => {
        if (!err) {
          let errTemp = {}
          if (!isUploadHidden && !screenshot) {
            errTemp = {
              ...errTemp,
              screenshot: 'Please upload screenshot file'
            }
          }
          if (isEmpty(errTemp)) {
            const [
              extraPointsByPP,
              extraPointsRequested,
              pointsFromProvider,
              recruitmentBonus,
              overridingBonus,
              royaltyBonus,
              founderBonus
            ] = [
              values.extra_points_by_pp || 0,
              values.extra_points_requested || 0,
              values.points_from_provider || 0,
              values.recruitment_bonus || 0,
              values.overriding_bonus || 0,
              values.royalty_bonus || 0,
              values.founder_bonus || 0
            ]
            const finalData = {
              extra_points_by_pp: extraPointsByPP,
              extra_points_requested: extraPointsRequested,
              points_from_provider: pointsFromProvider,
              points_rate:
                extraPointsByPP + extraPointsRequested + pointsFromProvider,
              link_for_email_approval: screenshot,
              recruitment_bonus: recruitmentBonus,
              overriding_bonus: overridingBonus,
              royalty_bonus: royaltyBonus,
              founder_bonus: founderBonus
            }
            if (binderType) {
              finalData.binder_type = binderType
            }
            updateCommissionRequest({
              policyNo: policyId,
              body: finalData
            })
          } else {
            setErrorObj(errTemp)
          }
        }
      })
    },
    [screenshot, policyId, updateCommissionRequest, validateFields, binderType, isUploadHidden]
  )

  const totalCommissions = useMemo(() => ({
    commission: outgoingCommissionRate ?? 0,
    point: pointsFromProvider ?? 0,
    total: (outgoingCommissionRate ?? 0) + (pointsFromProvider ?? 0)
  }), [outgoingCommissionRate, pointsFromProvider])
  return (
    <LayoutContentStyle className='details-info-container policy-detail-card'>
      <CommissionEditStyle>
        {(isO2O || (isOffline)) && (
          <SwitchContainer>
            <Radio.Group
              defaultValue=''
              value={binderType}
              onChange={handleChangeBinderData}
              disabled={isDisableFields}
              className='custom-radio-group'
            >
              <Radio.Button
                value='inside'
                className='custom-radio-button'
              >
                Inside Binder {binderType === 'inside' && <Icon type='check' />}
              </Radio.Button>
              <Radio.Button
                value='outside'
                className='custom-radio-button'
              >
                Outside Binder{' '}
                {binderType === 'outside' && <Icon type='check' />}
              </Radio.Button>
            </Radio.Group>
          </SwitchContainer>
        )}
        <div className='mt-20 text-label'>
          Current Total Outgoing Commission: {totalCommissions.total}%
          &nbsp;(Total commission more than 100% is not allowed)
        </div>
        {totalCommissions.total > 100 && (
          <div className='errorText'>The total commission exceeds 100%.</div>
        )}
        <Form className='mt-20' onSubmit={handleSubmit}>
          <div className='grid-2'>
            {renderForm(policyDetails, getCommissionsPointsData)}
          </div>
          {
            !isUploadHidden && (
              <>
                <div className='mt-20'>
                  <span className='required-star'>*</span> Upload screenshot of email approval
                </div>
                <div className='errorText'>{errorObj.screenshot}</div>
                <UploadImgPreview
                  onSave={(file) => handleSaveNewUploadImg(file, 'screenshot')}
                  name='screenshot'
                  img={screenshot}
                  isNew={!screenshot}
                  isPreviewImg
                  fileType='.jpg,.jpeg,.png'
                  onRemove={() => handleRemoveImg('screenshot')}
                  // Enabled when commission is in edit state OR when agent is LV and policy is Offline
                  disabled={!(commissionApprovalStatus === 'pending-commission-points-edit' || (isLVAgent && isOffline))}
                />
              </>
            )
          }
          {commissionApprovalStatus === 'pending-commission-points-edit' && (
            <Row justify='end' type='flex'>
              <Popconfirm
                title={`The total commission that will be disbursed is ${totalCommissions.commission}% & point is ${totalCommissions.point || 0}%. Is this correct? `}
                okText='YES'
                cancelText='NO'
                onConfirm={handleSubmit}
              >
                <Button
                  className='mt-20'
                  type='primary'
                  htmlType='submit'
                  disabled={totalCommissions.total > 100}
                  title={totalCommissions.total > 100 ? 'The total commission exceeds 100%.' : ''}
                >
                  Submit
                </Button>
              </Popconfirm>
            </Row>
          )}
        </Form>
      </CommissionEditStyle>
    </LayoutContentStyle>
  )
}

const wrapperCommissionEdit = Form.create()(CommissionEdit)

export default wrapperCommissionEdit
