import React, { Component } from 'react'
import { Row, Col, Table } from 'antd'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import moment from 'moment'
class AdditionalAddons extends Component {
  render () {
    const { addonsData, addsOnRequest } = this.props

    const currentYear = moment().year()
    const addsOnCategory = addsOnRequest?.add_ons_cat || []
    const isEvVariant = addsOnRequest?.ev_variant || false
    const brandVariant = isEvVariant ? 'ev_variant' : 'non_ev_variant'
    const ageYears = currentYear - addsOnRequest?.year

    const columns = [
      {
        title: 'Service Type',
        dataIndex: 'category'
      },
      {
        title: 'Service Name',
        dataIndex: 'name'
      },
      {
        title: 'AWS Rate(%)',
        dataIndex: 'category_code',
        render: (category_code, record) => {
          const addsOn = addsOnCategory?.find((cat) => cat?.category_code === category_code)?.add_on || []
          const addsOnByCode = addsOn?.find((addOn) => addOn?.add_on_code === record?.code) || {}
          const brandBaseYearRanges = Object.entries(addsOnByCode?.percentage?.brand_based_year_ranges || {})?.map(([brand, value]) => ({
              brand,
              data: value,
          }));  

          const brandOthersBaseYearData = brandBaseYearRanges?.find((item) => item?.brand === "others")?.data?.[`${brandVariant}`] || {}
          const brandBaseYearData = brandBaseYearRanges?.find((item) => item?.brand === addsOnRequest?.brand_code)?.data?.[`${brandVariant}`] || brandOthersBaseYearData

          const awsPercentageKey = Object?.keys(brandBaseYearData)
            ?.map(Number)
            ?.sort((a, b) => a - b)
            ?.find((key) => key >= ageYears)
          const awsPercentage = awsPercentageKey !== undefined ? brandBaseYearData[awsPercentageKey] : 0
          const isAws = record?.code === "authorized-service"

          return <span>{isAws ? `${awsPercentage}%` : "-"}</span>
        }
      },
      {
        title: 'Additional Fee(Rp)',
        dataIndex: 'premium'
      },
      {
        title: 'Sum Insured(Rp)',
        dataIndex: 'sum_insured'
      },
      {
        title: 'Add On Count',
        dataIndex: 'add_on_count'
      }
    ]

    return (
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title'>Additional Package (Addons)</h3>
          <Col span={24}>
            <Table
              pagination={{
                pageSize: 100
              }}
              columns={columns}
              rowKey={rowData => rowData.id}
              dataSource={addonsData}
              bordered
            />
          </Col>
        </Row>
      </LayoutContent>
    )
  }
}

export default AdditionalAddons
