import { useState, useMemo, useCallback, useEffect } from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Table,
  Button,
  Form,
  message
} from 'antd'
import { capitalizeFirstLetter } from '../../../../helpers/utility'
import LayoutContent from '../../../../components/utility/layoutContent'
import { EditObjectDetailFormStyle } from './policy.style'
import { usePolicyEditItemDataV2 } from './state/hooks/useAgentPolicyState'
import EditFieldModal from './components/EditFieldModal/EditFieldModal'
import agentAction from '../../../redux/agent/actions'
import { useParams } from 'react-router'
import { handleValidateNIK } from './helpers'
import PermissionCheckerV2 from '../../../../components/permissionCheckerV2'
import { handleValidatePolicyState, canEditField } from './utility'

const { getAgentInsuranceData, getVehicleValidYears } = agentAction

const ObjectDetail = (props) => {
  const {
    additionalDetail,
    policyDetailState,
    userEmail,
    dispatch,
    productId,
    vehicleValidYears,
    policyDataEdit
  } = props
  const { policy_id: policyId } = useParams()
  const [, submitEditPolicyFormReq] = usePolicyEditItemDataV2()
  const [isEditableModalVisible, setIsEditableModalVisible] = useState(false)
  const [editableFieldKey, setEditableFieldKey] = useState('')
  const [editableFieldValue, setEditableFieldValue] = useState('')
  const [editableFieldUserInput, setEditableFieldUserInput] = useState('')
  const [editableFieldUserInputRemarks, setEditableFieldUserInputRemarks] = useState('')
  const [editableFieldError, setEditableFieldError] = useState('')
  const handleChangeInput = (val) => {
    if (editableFieldError) setEditableFieldError('')
    setEditableFieldUserInput(val)
  }

  useEffect(() => {
    if (additionalDetail && additionalDetail.model) {
      dispatch(getVehicleValidYears(additionalDetail.variant_code))
    }
  }, [additionalDetail, dispatch])

  const handleCloseEditableModal = () => {
    setIsEditableModalVisible(false)
    setEditableFieldKey('')
    setEditableFieldValue('')
    setEditableFieldUserInput('')
    setEditableFieldUserInputRemarks('')
    setEditableFieldError('')
  }

  const handleOpenEditableModal = (fieldKey) => {
    setIsEditableModalVisible(true)
    setEditableFieldKey(fieldKey)
    setEditableFieldValue(additionalDetail[fieldKey])
    setEditableFieldUserInput(additionalDetail[fieldKey])
    setEditableFieldError('')
  }

  const handleSubmit = async () => {
    try {
      setEditableFieldError('')
      handleValidatePolicyState(policyDetailState)
      if (editableFieldKey === 'ktp_no') {
        handleValidateNIK(editableFieldUserInput)
      }

      await submitEditPolicyFormReq({
        policyId,
        body: {
          processed_by: userEmail,
          data: {
            [editableFieldKey]: {
              value: editableFieldUserInput,
              remarks: editableFieldUserInputRemarks
            }
          }
        }
      })

      dispatch(getAgentInsuranceData({ policyId }))
      handleCloseEditableModal()
    } catch (error) {
      // Keep the modal open and show backend validation error (if any)
      const errMsg = (error && (
        (error.response && error.response.data && (error.response.data.message || error.response.data.error)) ||
        error.message
      )) || 'Failed to save changes. Please check your input.'
      setEditableFieldError(typeof errMsg === 'string' ? errMsg : JSON.stringify(errMsg))
      // also surface a toast for visibility
      message.error(typeof errMsg === 'string' ? errMsg : 'Failed to save changes. Please check your input.')
    }
  }

  const getAmountString = useCallback((type, value) => {
    switch (type) {
      case 'vehicle_sum_insured':
        return `Rp ${new Intl.NumberFormat().format(value)}`
      case 'region_code':
        return additionalDetail.region_type
      case 'vehicle_plate_no':
        return `${additionalDetail.region_code} ${value}`
      default:
        return value
    }
  }, [additionalDetail])

  const columns = [
    {
      dataIndex: 'name',
      width: 150
    },
    {
      dataIndex: 'value',
      render: (text, record) => (
        <EditObjectDetailFormStyle>
          {text}
          {record.isEditable && (
            <PermissionCheckerV2 requiredPermission='ops.edit_agency_object_detail'>
              <Button
                icon='edit'
                onClick={() => handleOpenEditableModal(record.fieldKey)}
                style={{ marginLeft: 8 }}
              >
                Edit
              </Button>
            </PermissionCheckerV2>
          )}
        </EditObjectDetailFormStyle>
      )
    }
  ]

  const columnPolicyDetailsReq = useMemo(() => {
    const result = []
    let count = 0
    for (const key in additionalDetail) {
      if (typeof additionalDetail[key] !== 'object') {
        const policyDataEditField = canEditField(key, policyDetailState, productId, policyDataEdit)
        result.push({
          key: count,
          name:
            key === 'odometer_value'
              ? <strong>Mileage</strong>
              : <strong>{capitalizeFirstLetter(key)}</strong>,
          value:
            additionalDetail[key] !== undefined
              ? getAmountString(key, additionalDetail[key])
              : '-',
          isEditable: !!policyDataEditField,
          fieldKey: key,
          policyDataEditField
        })
        count++
      }
    }
    return result
  }, [getAmountString, additionalDetail, policyDetailState, productId, policyDataEdit])

  return (
    <LayoutContent className='details-info-container policy-detail-card'>
      <Row>
        <h3 className='policy-title'>Object Insured Details</h3>
        <Col span={24}>
          <Table
            pagination={{ pageSize: 100 }}
            showHeader={false}
            columns={columns}
            dataSource={columnPolicyDetailsReq}
          />
        </Col>
      </Row>
      <EditFieldModal
        visible={isEditableModalVisible}
        title={`Edit ${capitalizeFirstLetter(editableFieldKey)}`}
        editableFieldKey={editableFieldKey}
        editableFieldValue={editableFieldValue}
        editableFieldUserInput={editableFieldUserInput}
        editableFieldUserInputRemarks={editableFieldUserInputRemarks}
        fieldError={editableFieldError}
        regionCode={additionalDetail && additionalDetail.region_code}
        onClose={handleCloseEditableModal}
        onChangeInput={handleChangeInput}
        onChangeRemarks={setEditableFieldUserInputRemarks}
        onSubmit={handleSubmit}
        vehicleValidYears={vehicleValidYears}
      />
    </LayoutContent>
  )
}

const mapStateToProps = (state) => ({
  agentPolicy: state.Agent.agentPolicy,
  vehicleValidYears: state.Agent.vehicleValidYears || []
})

export default connect(mapStateToProps)(Form.create()(ObjectDetail))
