import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, Row, Input, Col, Form } from 'antd'
import { NotesStyle } from './index.style'

class AcceptDocumentModal extends Component {
    static propTypes = {
      isShowModal: PropTypes.bool,
      onSubmit: PropTypes.func,
      onCancel: PropTypes.func
    }

    state = {
      additionalRemark: ''
    }

    handleAcceptDocument = (e) => {
      this.setState({
        additionalRemark: e.target.value
      })
    }

    handleSubmit = () => {
      this.props.onSubmit(this.state.additionalRemark)
    }

    render () {
      const { isShowModal } = this.props
      return (
        <Modal
          title='Accept Document'
          visible={isShowModal}
          onOk={this.handleSubmit}
          onCancel={this.props.onCancel}
          okText='Submit'
        >
          <Row>
            <Col>
              <Form.Item>
                <Input.TextArea placeholder='Input additional remarks to provider if necessary' onChange={(e) => this.handleAcceptDocument(e)} />
              </Form.Item>
              <NotesStyle>
                Additional information entered is displayed in the <strong>Special Notes</strong> section of the policy detail page. This information will also be visible to the insurance.
              </NotesStyle>
            </Col>
          </Row>
        </Modal>
      )
    }
}

export default (AcceptDocumentModal)
