import { Col, Icon, Modal, Row, Select, Upload, Button, message, DatePicker } from 'antd'
import TextArea from 'antd/lib/input/TextArea'
import { useCallback, useRef, useState, useEffect, useMemo } from 'react'
import moment from 'moment-timezone'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../constants'
import { POLICY_CANCEL_REASONS } from '../../constants'
import { PolicyCancelStyle } from './index.style'
import { connect } from 'react-redux'
import policyActions from '../../../../../../redux/policy/actions'
import CircularLoader from '../../../../../../components/CircularLoader'

const { uploadPolicyFile, resetReduxState: policyResetReduxState } = policyActions

function PolicyCancelModal (props) {
  const { show, loader, onClose, onSubmit, uploadPolicyFile, isCancelled, completedPolicy, documentNotMandatory } = props
  const [policyCancelDocument, setPolicyCancelDocument] = useState('')
  const [uploadingStatus, setUploadingStatus] = useState(false)

  const [cancelReason, setCancelReason] = useState('')
  const [error, setError] = useState('')
  const [cancellationDate, setCancellationDate] = useState(null)
  // if Other text selected then we need to show textarea
  const otherText = POLICY_CANCEL_REASONS[POLICY_CANCEL_REASONS.length - 1]
  const otherReason = useRef()
  const that = useRef({
    isCallStart: false
  })

  const handleSelectChange = useCallback((cancelReason) => {
    // handle the select changes
    if (cancelReason !== otherText) {
      otherReason.current = ''
    }
    setCancelReason(cancelReason)
  }, [otherText])

  const handleOtherReason = useCallback((e) => {
    otherReason.current = e.target.value
  }, [])

  const handleOnOk = useCallback(() => {
    if (isCancelled) {
      if (!that.current.isCallStart) {
        that.current.isCallStart = true
        const payload = {
          cancellation_document: policyCancelDocument
        }
        // Only include cancellation_date if a date is selected
        if (cancellationDate) {
          payload.cancellation_date = moment(cancellationDate).format('YYYY-MM-DD')
        }
        onSubmit(payload, isCancelled)
      }
      return
    }
    if (cancelReason === otherText && !otherReason.current) {
      setError(true)
      return
    }
    setError(false)
    if (!that.current.isCallStart) {
      that.current.isCallStart = true
      const payload = {
        reason: cancelReason === otherText ? otherReason.current : cancelReason,
        cancellation_document: policyCancelDocument
      }
      // Only include cancellation_date if a date is selected
      if (cancellationDate) {
        payload.cancellation_date = moment(cancellationDate).format('YYYY-MM-DD')
      }
      onSubmit(payload, false, completedPolicy)
    }
  }, [onSubmit, cancelReason, otherText, policyCancelDocument, cancellationDate, isCancelled, completedPolicy])

  const beforeUpload = (file) => {
    // file size validation for 10MB
    const isLt10M = file.size / 1024 / 1024 <= 10
    if (!isLt10M) {
      message.error('file must smaller than 10MB!')
    }
    return isLt10M
  }

  const customRequest = ({ file }) => {
    const formData = new FormData()
    // we are sending this values for storage identification
    // can we upload any type of file like png, jpg, pdf
    if (file.name) {
      const fileName = file.name.split('.')[0]
      formData.append('file', file)
      formData.append('path', `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${Date.parse(new Date())}`)
      formData.append('identifier', 'agent')
      uploadPolicyFile({ body: formData })
      setUploadingStatus(true)
    }
  }

  const onRemoveEndorsmentFile = useCallback(() => {
    setPolicyCancelDocument('')
  }, [])

  const handleDateChange = useCallback((date) => {
    setCancellationDate(date)
  }, [])

  useEffect(() => {
    if (props.uploadPolicyFileStatus === 'success') {
      setPolicyCancelDocument(props.uploadPolicyFileData.url)
      // clear the policy store after successful upload documents
      policyResetReduxState(['uploadPolicyFileStatus', 'uploadPolicyFileData'])
    }
    setUploadingStatus(false)
  }, [props.uploadPolicyFileStatus, props.uploadPolicyFileData,
    props.uploadPolicyFileLoading
  ])

  useEffect(() => {
    if (!show) {
      setCancellationDate(null)
      setPolicyCancelDocument('')
      setCancelReason('')
      setError('')
      that.current.isCallStart = false
    }
  }, [show])

  const disableOkButton = useMemo(() => {
    // If policy is already cancelled: disabled when no cancellation document is uploaded
    if (isCancelled) return !policyCancelDocument

    // If policy is not cancelled and document is not mandatory: disabled when no cancel reason is selected
    if (documentNotMandatory) return !cancelReason

    // If policy is not cancelled and document is mandatory: disabled when user has not input data
    return (!cancelReason || !policyCancelDocument || uploadingStatus || !cancellationDate)
  }, [isCancelled, policyCancelDocument, documentNotMandatory, cancelReason, uploadingStatus, cancellationDate])

  return (
    <Modal
      visible={show}
      onCancel={onClose}
      title={isCancelled ? 'Cancellation Document' : 'Policy Cancellation'}
      onOk={handleOnOk}
      okButtonProps={{
        disabled: disableOkButton,
        loading: loader
      }}
    >
      <PolicyCancelStyle>
        {
          !isCancelled && (
            <>
              <Row type='flex'>
                <Col xl={4} md={4} sm={4} className='reason-text'>Alasan</Col>
                <Col xl={24} md={24} sm={24}>
                  <Select className='cancel-select-width' onChange={handleSelectChange}>
                    {
                      POLICY_CANCEL_REASONS.map((item, index) => (
                        <Select.Option value={item} key={`cancel_${index}`}>{item}</Select.Option>
                      ))
                    }
                  </Select>
                </Col>
              </Row>
              {
                cancelReason === otherText && <TextArea className='reason-textarea' onChange={handleOtherReason} />
              }
              {
                error && <div className='other-reason-error'>Please Provide Other Reason</div>
              }
              <br />
            </>
          )
        }
        <br />
        <Row type='flex' style={{ marginBottom: 16 }}>
          <Col xl={4} md={4} sm={4} className='reason-text'>Request Date</Col>
          <Col xl={24} md={24} sm={24}>
            <DatePicker
              format='YYYY-MM-DD'
              value={cancellationDate}
              onChange={handleDateChange}
              style={{ width: '100%' }}
              placeholder='Select request date'
            />
          </Col>
        </Row>
        <br />
        <Row type='flex'>
          <Col
            xl={24}
            md={24}
            sm={24}
            className='reason-text'
          >
            {
              isCancelled
                ? <>Upload cancellation document from provider (PDF file)<span style={{ color: 'red' }}>*</span></>
                : 'Policy Cancellation Documents'
            }
          </Col>
          <Col xl={24} md={24} sm={24} className='reason-text'><br /></Col>
          <Col xl={24} md={24} sm={24}>
            {
              policyCancelDocument
                ? (
                  <>
                    <div className='documents-container'>
                      <object
                        type='application/pdf'
                        data={policyCancelDocument}
                        width={150}
                        height={150}
                        aria-label='Policy Doc Pdf'
                      />
                      <div className='cross-mark' onClick={onRemoveEndorsmentFile}>
                        <Icon type='cross' />
                      </div>
                    </div>
                  </>
                  )
                : (
                  <Upload
                    name='upload'
                    showUploadList={false}
                    customRequest={(data) => customRequest(data)}
                    listType='picture'
                    accept='.pdf'
                    beforeUpload={(file) => { return beforeUpload(file) }}
                  >
                    {
                      uploadingStatus
                        ? <CircularLoader isSpining />
                        : (
                          <Button>
                            <Icon type='upload' /> Click to upload
                          </Button>
                          )
                    }
                  </Upload>
                  )
            }
          </Col>
        </Row>
        <div className='cancel-notification'>
          {
            !isCancelled
              ? 'The policy will be canceled as soon as your form is submitted. Mitra will receive notification emails regarding your policy cancellation!'
              : 'Make sure the document you want to upload is correct. The document you choose is directly uploaded and appears immediately in the Mitra app after submitting the form.'
          }
        </div>
      </PolicyCancelStyle>
    </Modal>
  )
}

export default connect(
  (state) => ({
    uploadPolicyFileLoading: state.Loading.UPLOAD_FILE,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData
  }),
  {
    uploadPolicyFile,
    policyResetReduxState
  }
)(PolicyCancelModal)
