export const toUpper = value => (value || '').toUpperCase()
export const digitsOnly = value => (value || '').replace(/\D/g, '')
export const lettersAndSpaces = value => (value || '').replace(/[^A-Za-z ]/g, '')

export const normalizePlate = value => toUpper(value).trim().replace(/\s+/g, '')

export const isValidPlate = value => normalizePlate(value).length > 0

export const validators = {
  ktp_no: value => digitsOnly(value).length === 16,
  chasis_number: value => {
    const vin = toUpper(value).trim()
    return vin.length >= 8 && vin.length <= 20 && /^[A-Z0-9]+$/.test(vin)
  },
  machine_number: value => {
    const machineNumber = toUpper(value).trim()
    return machineNumber.length >= 5 && machineNumber.length <= 21 && /^[A-Z0-9]+$/.test(machineNumber)
  },
  vehicle_plate_no: isValidPlate,
  color: value => {
    const color = (value || '').trim()
    return color.length > 0 && /^[A-Za-z ]+$/.test(color)
  }
}
