import { Col, Row, Table } from 'antd'
import { get } from 'lodash'
import LayoutContent from '../../../../components/utility/layoutContent'
import { capitalizeFirstLetter } from '../../../../helpers/utility'

function FamilyTravelDetails ({ agentPolicy }) {
  const grpInfo = get(agentPolicy, 'additional_detail.extra_data.customer_data') || {}
  const customerData = get(agentPolicy, 'additional_detail.extra_data.customer_data') || {}
  const mainTraveller = get(customerData, 'main_traveller', {})
  const { kids = 0, adult = 0 } = get(agentPolicy, 'additional_detail.extra_data.additional_member_count', {})
  const policyType = get(agentPolicy, 'additional_detail.policy_type') || {}

  const customerFieldLabels = {
    name: 'Name',
    email: 'Email',
    gender: 'Gender',
    address: 'Address',
    mobile_no: 'Mobile No',
    insured_id: 'Insured id',
    date_of_birth: 'Date of birth',
    insured_id_type: 'Insured id type'
  }

  const customerKeyValuePairs = Object.entries(customerFieldLabels).map(([key, label]) => ({
    label,
    value: get(grpInfo, key, '-') 
  }))

  const columns = [
  {
    key: 'name',
    dataIndex: 'name',
    title: 'Name'
  },
  {
    key: 'gender',
    dataIndex: 'gender',
    title: 'Jenis Kelamin/ Gender'
  },
  {
    key: 'date_of_birth',
    dataIndex: 'date_of_birth',
    title: 'Tanggal Lahir/ Date of birth'
  },
  {
    key: 'insured_id',
    dataIndex: 'insured_id',
    title: 'Nomor id/ Id no'
  },
  {
    key: 'doucment_type',
    title: 'Document Type',
    dataIndex: 'insured_id_type'
  },
  {
    key: 'relation',
    dataIndex: 'relation',
    title: 'Relation/ Date of birth',
    hideForGroup: true 
  }
].filter(col => !(policyType === 'group' && col.hideForGroup))

  const data = [
    ...(get(customerData, 'adults', []).map((item) => { return { ...item, relation: 'Istri/ Partner' } })),
    ...get(customerData, 'kids', []).map((item) => { return { ...item, relation: 'Anak/ Child' } })
  ]

  const mainTravellercolumns = [
    {
      dataIndex: 'name',
      width: 150
    }, {
      dataIndex: 'value'
    }
  ]

  const grpTravellerColumns = [
  {
    title: <strong>Field</strong>,
    dataIndex: 'label',
    key: 'label',
    width: 150,
    render: (text) => <strong>{text}</strong>
  },
  {
    title: 'Value',
    dataIndex: 'value',
    key: 'value'
  }
]

  const mainTravellerData = []

  for (const key in mainTraveller) {
    mainTravellerData.push({
      id: key,
      name: <strong>{capitalizeFirstLetter(key)}</strong>,
      value: mainTraveller[key]
    })
  }

  return (
    <>
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title'>Policy Details</h3>
          {agentPolicy.request.policy_type === 'group' ? 
          <Col span={24}>
            <Table
              pagination={{
                pageSize: 100
              }}
              showHeader={false}
              rowKey='insured_id'
              columns={grpTravellerColumns}
              dataSource={customerKeyValuePairs}
            />
          </Col>
          :
          <Col span={24}>
              <Table
                pagination={{
                  pageSize: 100
                }}
                showHeader={false}
                rowKey={data => data.id}
                columns={mainTravellercolumns}
                dataSource={mainTravellerData}
              />
            </Col>}
        </Row>

      </LayoutContent>
      {agentPolicy.request.policy_type === 'group' ? null : (
        kids + adult ? (
          <LayoutContent className='details-info-container policy-detail-card'>
            <h3 className='policy-title'>Customer Data</h3>
            <Table
              columns={columns}
              dataSource={data}
            />
          </LayoutContent>
        ) : null
      )}
    </>
  )
}

export default FamilyTravelDetails
