import { EndorsementDetailStyle } from './index.style'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import Dates from '../../PolicyEndorsement/components/Dates'
import Attachments from '../../PolicyEndorsement/components/Attachments'
import get from 'lodash/get'
import { useCallback } from 'react'
import { Row, Col, Button } from 'antd'
import { isEmpty } from 'lodash'
import ModalImage from 'react-modal-image'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import { getPaymentStatus } from '../../../constants'

function EndorsementDetail (props) {
  const { num, data, id, policyDetails, endorsementId } = props
  const endorsementData = get(data, 'endorsement_data', {})

  const downloadPdf = useCallback((fileUrl) => {
    window.open(fileUrl)
  }, [])

  const renderImageObject = useCallback((fileUrl) => {
    const fileExt = getUrlExtension(fileUrl)
    if (fileExt === 'pdf') {
      return (
        <div className='documents-container'>
          <div className='pdf-container'>
            <object
              type='application/pdf'
              data={fileUrl}
              width='150'
              height='150'
              aria-label='PDF'
            />
            <div className='view-pdf-btn-container'>
              <Button
                onClick={() => downloadPdf(fileUrl)}
              >
                View Pdf
              </Button>
            </div>
          </div>
        </div>
      )
    } else {
      return (
        <div className='documents-container'>
          <ModalImage
            className='policy-img'
            small={fileUrl}
            large={fileUrl}
            name=''
            imageBackgroundColor='transparent'
          />
        </div>
      )
    }
  }, [downloadPdf])

  const renderCol = useCallback((index, ed = {}) => {
    return (
      <Col
        key={`formData_${index}`}
        className='form-col-width field-margin'
      >
        <h3>
          {ed.title}
        </h3>
        <div>
          {ed.value}
        </div>
      </Col>
    )
  }, [])

  const renderEndorsementData = useCallback(() => {
    return Object.keys(endorsementData).map((endorKey, i) => {
      return (
        <div key={`endorseDataDetail_${i}`}>
          <h2> {endorKey} </h2>
          <Row type='flex' justify='start'>
            {
              endorsementData[endorKey].map((ed, index) => renderCol(index, ed))
            }
            {
              (endorKey === 'Others') && (data?.agencyEndorsementData?.payment_status && (data?.agencyEndorsementData?.payment_status !== 'NOT_REQUIRED')) &&
                <>
                  {
                    renderCol('invoice', {
                      title: 'Invoice',
                      value: get(data, 'agencyEndorsementData.invoice_url', '') ? renderImageObject(data?.agencyEndorsementData.invoice_url) : '-'
                    })
                  }
                  {
                    renderCol('PaymentStatus', {
                      title: 'Payment Status',
                      value: get(data, 'agencyEndorsementData.payment_status', '') ? getPaymentStatus(data?.agencyEndorsementData.payment_status).text : '-'
                    })
                  }
                </>
            }
          </Row>
          <hr />
        </div>
      )
    })
  }, [endorsementData, renderCol, renderImageObject, data])

  const renderPaymentStatus = useCallback(() => {
    return (
      <div key='endorseDataDetailPaymentStatus'>
        <h2>Payment</h2>
        <Row type='flex' justify='start'>
          {
            [
              renderCol('PaymentBy', {
                title: 'Payment By',
                value: get(data, 'agencyEndorsementData.paid_by', '') || '-'
              }),
              renderCol('PaymentTo', {
                title: 'Payment To',
                value: get(data, 'agencyEndorsementData.paid_to', '') || '-'
              }),
              renderCol('totalPayment', {
                title: 'Total Amount',
                value: get(data, 'agencyEndorsementData.total_payment', '') || '-'
              }),
              renderCol('PaymentDate', {
                title: 'Payment Date',
                value: get(data, 'agencyEndorsementData.payment_date', '') || '-'
              })
            ]
          }
        </Row>
      </div>
    )
  }, [renderCol, data])

  return (
    <LayoutContent className='details-info-container policy-detail-card' id={id}>
      <EndorsementDetailStyle>
        <h2 className='policy-title'>Policy Endorsement {num}</h2>
        <br />
        <Dates
          reviewData={data}
          isDetail
        />
        <hr />
        <Attachments
          proofImages={policyDetails?.endorsement_proof_images[endorsementId]}
          reviewData={data}
          isDetail
        />
        <hr />
        {
          (!isEmpty(endorsementData)) && renderEndorsementData()
        }
        {
          data?.agencyEndorsementData?.payment_status && (data?.agencyEndorsementData?.payment_status !== 'NOT_REQUIRED') && renderPaymentStatus()
        }
      </EndorsementDetailStyle>
    </LayoutContent>
  )
}

export default EndorsementDetail
