import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { isEmpty } from 'lodash'
import get from 'lodash/get'
import { useCallback, useEffect } from 'react'
import { showNotification } from '../../../../../../components/ShowNotification'
import { useGetReconPolicyDetails } from '../../state/hooks/useAgentPolicyState'
import ObjectTable from '../ObjectTable'

function ReconDetails (props) {
  const { policyNo } = props
  // const getReconPolicyDetailsData={}
  const [{ getReconPolicyDetailsData = {} }, getReconPolicyDetailsRequest] = useGetReconPolicyDetails()
  const [{ GET_RECON_POLICY_DETAILS_LOADER }
  ] = useLoaderContextValue()

  const [{ GET_RECON_POLICY_DETAILS_ERROR, getReconPolicyDetailsStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (getReconPolicyDetailsStatus && GET_RECON_POLICY_DETAILS_ERROR) {
      showNotification('error', getReconPolicyDetailsStatus)
      dispatchError(resetError({
        getReconPolicyDetailsStatus: ''
      }))
    }
  }, [getReconPolicyDetailsStatus, GET_RECON_POLICY_DETAILS_ERROR,
    dispatchError
  ])

  useEffect(() => {
    getReconPolicyDetailsRequest({
      policyNo
    })
  }, [getReconPolicyDetailsRequest,
    policyNo
  ])

  const renderTableContent = (key) => {
    const policyDataByKey = getReconPolicyDetailsData[key]
    const ojkReconType = policyDataByKey?.filter((item) => item.recon_type === 'OJK')
    const extraCommissionReconType = policyDataByKey?.filter((item) => item.recon_type === 'EXTRA_COMMISSION')
    const length = ojkReconType?.length > extraCommissionReconType?.length ? ojkReconType?.length : extraCommissionReconType?.length

    return length
      ? [...Array(length)].map((_, index) => {
          return (
            <ObjectTable
              key={index}
              title={key === 'NEW' ? 'Recon Details' : 'Recon Endorsement Details'}
              tableColumns={handlerGetData([ojkReconType[index], extraCommissionReconType[index]])}
            />
          )
        })
      : []
  }

  const handlerGetData = useCallback((row) => {
    const newOjk = row[0] || {}
    const newExtra = row[1] || {}

    return [
      {
        key: 'holder_1',
        name: '',
        value: <strong>OJK Commision</strong>,
        value1: <strong>EXTRA Commision</strong>
      },
      {
        key: 'holder_1',
        name: <strong>Recon Name</strong>,
        value: get(newOjk, 'recon_name', ''),
        value1: get(newExtra, 'recon_name', '')
      },
      {
        key: 'holder_2',
        name: <strong>Payment Date</strong>,
        value: get(newOjk, 'payment_date', ''),
        value1: get(newExtra, 'payment_date', '')
      },
      {
        key: 'holder_3',
        name: <strong>Commission %</strong>,
        value: get(newOjk, 'commission_percent', ''),
        value1: get(newExtra, 'commission_percent', '')
      },
      {
        key: 'holder_4',
        name: <strong>Commission Amount</strong>,
        value: get(newOjk, 'commission_amount', ''),
        value1: get(newExtra, 'commission_amount', '')
      },
      {
        key: 'holder_5',
        name: <strong>VAT 10%</strong>,
        value: get(newOjk, 'vat_amount', ''),
        value1: get(newExtra, 'vat_amount', '')
      },
      {
        key: 'holder_6',
        name: <strong>WHT PPH23 2%</strong>,
        value: get(newOjk, 'wht_amount', ''),
        value1: get(newExtra, 'wht_amount', '')
      },
      {
        key: 'holder_7',
        name: <strong>Total Payment</strong>,
        value: get(newOjk, 'payment', ''),
        value1: get(newExtra, 'payment', '')
      },
      {
        key: 'holder_8',
        name: <strong>Commission Revenue</strong>,
        value: get(newOjk, 'commission_revenue', ''),
        value1: get(newExtra, 'commission_revenue', '')
      },
      {
        key: 'holder_9',
        name: <strong>Remark</strong>,
        value: get(newOjk, 'remarks', ''),
        value1: get(newExtra, 'remarks', '')
      }
    ]
  }, [])

  if (GET_RECON_POLICY_DETAILS_LOADER !== undefined && isEmpty(getReconPolicyDetailsData)) {
    return (
      <div>
        Recon data is not available
      </div>
    )
  }

  if (GET_RECON_POLICY_DETAILS_LOADER !== undefined) {
    return (
      <>
        {renderTableContent('NEW')}
        {
          getReconPolicyDetailsData.ENDORSEMENT &&
          renderTableContent('ENDORSEMENT')
        }
      </>
    )
  }
  return null
}

export default ReconDetails
