import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Row, Col, Table, Upload } from 'antd'
import LayoutContent from '../../../../../components/utility/layoutContent'
import ModalImage from 'react-modal-image'
import { AccessoryStyle } from './index.style'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'

class AdditionalAccessories extends Component {
  static propTypes = {
    typeKey: PropTypes.string,
    isShowReuploadBtn: PropTypes.bool,
    additionalAccessories: PropTypes.array,
    relatedInsurances: PropTypes.array,
    onReupload: PropTypes.func
  }

  getRelatedPoliciesColumns = () => {
    // handle this info

    return [
      {
        title: 'Policy Type',
        dataIndex: 'policy_type',
        key: 'policy_type'
      },
      {
        title: 'Application Number',
        dataIndex: 'app_no',
        key: 'app_no'
      },
      {
        title: 'Policy Number',
        dataIndex: 'policy_number',
        key: 'policy_number'
      },
      {
        title: 'Policy State',
        dataIndex: 'policy_state',
        key: 'policy_state'
      },
      {
        title: 'Payment State',
        dataIndex: 'payment_status',
        key: 'payment_status'
      },
      {
        title: 'Policy Start Date',
        dataIndex: 'start_date',
        key: 'start_date'
      },
      {
        title: 'Policy End Date',
        dataIndex: 'end_date',
        key: 'end_date'
      }
    ]
  }

  render () {
    const { additionalAccessories, isShowReuploadBtn, relatedInsurances = [], typeKey } = this.props
    const columns = [
      {
        title: 'Photo',
        dataIndex: 'img',
        width: 300,
        render: (val) => (
          <AccessoryStyle>
            <ModalImage
              className='object-image'
              small={val}
              large={val}
            />
            {
              isShowReuploadBtn && (
                <PermissionCheckerV2 requiredPermission='ops.view_agent_policy_reupload_documents_btn'>
                  {
                    isShowReuploadBtn && (
                      <Upload
                        name='file'
                        accept='.jpg,.png,.jpeg'
                        multiple={false}
                        showUploadList={false}
                        customRequest={({ file }) => this.props.onReupload({
                          val,
                          key: 'accessories',
                          oldUrl: val,
                          file
                        })}
                        className='img-reupload-btn'
                      >
                        Reupload Document
                      </Upload>
                    )
                  }
                </PermissionCheckerV2>
              )
            }
          </AccessoryStyle>
        )
      }, {
        title: 'Accessories Name',
        dataIndex: 'name'
      },
      {
        title: 'Accessories Type',
        dataIndex: typeKey || 'type'
      }, {
        title: 'Pricing',
        dataIndex: 'sum_insured'
      }
    ]

    return (
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title'>Additional Accessories</h3>
          <Col span={24}>
            <Table
              pagination={{
                pageSize: 100
              }}
              columns={columns}
              dataSource={additionalAccessories}
              bordered
            />
          </Col>
        </Row>
        {
          !!relatedInsurances?.length && (
            <>
              <br />
              <Row>
                <h3 className='policy-title'>Related Policies</h3>
                <Col span={24}>
                  <Table
                    pagination={{
                      pageSize: 100
                    }}
                    columns={this.getRelatedPoliciesColumns()}
                    dataSource={relatedInsurances}
                    bordered
                  />
                </Col>
              </Row>
            </>
          )
        }
      </LayoutContent>
    )
  }
}

export default AdditionalAccessories
