
import React, { Component } from 'react'
import PropTypes from 'prop-types'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { Table } from 'antd'
import get from 'lodash/get'

class PolicyDoc extends Component {
  static propTypes = {
    policyDetails: PropTypes.object
  }

  render () {
    const { policyDetails = {} } = this.props
    const columns = [
      {
        title: 'Document Name',
        dataIndex: 'insurance_for'
      },
      {
        title: 'Policy Number',
        dataIndex: 'insurance_policy_no',
        render: (value) => {
          return value || '_'
        }
      },
      {
        title: 'Document',
        dataIndex: 'document_url',
        render: (value) => {
          return value ? <a href={value} target='_blank' rel='noopener noreferrer'>View File</a> : '_'
        }
      },
      {
        title: 'Commission/Credit Note',
        dataIndex: 'commission_note_url',
        render: (value) => {
          return value ? <a href={value} target='_blank' rel='noopener noreferrer'>View File</a> : '_'
        }
      }
    ]

    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>Policy Documents</h3>
          <Table
            pagination={{
              pageSize: 100
            }}
            rowKey={data => data.id}
            columns={columns}
            bordered
            dataSource={get(policyDetails, 'child_insurance', [])}
          />
        </div>
      </LayoutContentStyle>
    )
  }
}

export default PolicyDoc
