import React, { Component } from 'react'
import PropTypes from 'prop-types'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { Table } from 'antd'
import get from 'lodash/get'

class DocumentPendingOnAgent extends Component {
  static propTypes = {
    policyDetail: PropTypes.object
  }

  getRows = () => {
    const { policyDetail } = this.props
    return [
      {
        id: 'document_pending_1',
        name: <strong>Document's Pending</strong>,
        value: (get(policyDetail, 'data_pending_on_agent', '-') || '-')
      }
    ]
  }

  render () {
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      },
      {
        dataIndex: 'value'
      }
    ]

    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>Document Pending On Mitra</h3>
          <Table
            pagination={{
              pageSize: 100
            }}
            rowKey={data => data.id}
            showHeader={false}
            columns={columns}
            dataSource={this.getRows()}
          />
        </div>
      </LayoutContentStyle>
    )
  }
}

export default DocumentPendingOnAgent
