import { PhysicalDamageStyle } from './index.style'
import { useCallback, useMemo } from 'react'
import ModalImage from 'react-modal-image'

function PhysicalDamage ({ damagePhotos = {}, remark }) {
  const mappedImgs = useMemo(() => {
    const mapped = []
    for (const key in damagePhotos) {
      const item = damagePhotos[key]
      mapped.push((
        <div className='img-container'>
          <ModalImage
            className='policy-img'
            small={item.original}
            large={item.original}
            id={item}
            imageBackgroundColor='transparent'
          />
        </div>
      ))
    }
    return mapped.length ? mapped : null
  }, [damagePhotos])

  const renderPhysicalPhotos = useCallback(() => {
    return (
      <div className='damage-photos'>
        {mappedImgs || 'Not Provided'}
      </div>
    )
  }, [mappedImgs])

  return (
    <PhysicalDamageStyle className='details-info-container policy-detail-card'>
      <h3 className='policy-title'>Physical Damages</h3>
      <div className='damage-remarks'>Photos</div>
      {renderPhysicalPhotos()}
      <div className='damage-remarks'>Remarks</div>
      <p>{remark}</p>
    </PhysicalDamageStyle>
  )
}

export default PhysicalDamage
