import React, { useEffect, useState } from 'react'
import { useHistory } from 'react-router'
import { connect } from 'react-redux'
import { TableContainer, StyledTable, TableHeader, TableRow, TableCell, PaginationContainer, PageButton, ActionButton } from './ClaimListStyle.style'
import claimActions from '../../../../../redux/claims/actions'

const { getClaimLists, resetReduxStateClaim } = claimActions

const ClaimListComponent = ({
  data,
  getClaimLists,
  getClaimListsStatus,
  applicationNo,
  resetReduxStateClaim
}) => {
  const [claimData, setClaimData] = useState(null)
  const [claimMetaData, setClaimMetaData] = useState(null)
  const [claimListLoading, setClaimListLoading] = useState(false)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const [numPage, setNumPage] = useState(1)
  const history = useHistory()

  const dataClaims = !!claimData && claimData.map((val, index) => {
    return {
      key: index,
      claim_no: val.claim_no,
      benefit: val.benefit,
      created_at: val.created_at,
      status: val.status,
      claim_id: val.claim_id
    }
  })

  useEffect(() => {
    if (getClaimListsStatus === 'success' && data) {
      setClaimData(data.data)
      setClaimMetaData(data.meta_data)
    }
  }, [getClaimListsStatus, data])

  useEffect(() => {
    if (applicationNo) {
      getClaimLists({ application_no: applicationNo })
    }
    return () => {
      resetReduxStateClaim(['getClaimListsStatus'])
    }
  }, [getClaimLists, applicationNo, resetReduxStateClaim])

  useEffect(() => {
    if (claimData && claimMetaData) {
      setClaimListLoading(false)
      setCurrentPage(claimMetaData.page)
      setPageSize(claimMetaData.page_size)
      setNumPage(claimMetaData.num_page)
    }
  }, [claimData, claimMetaData])

  const handlePaginationChange = (page) => {
    setClaimListLoading(true)
    getClaimLists({ application_no: applicationNo, page: page, page_size: pageSize })
  }

  return dataClaims?.length
    ? (
      <TableContainer>
        <div className='policy-header'>
          <h1 className='policy-title'>Claim List</h1>
        </div>
        {claimListLoading
          ? (
            <p>Loading...</p>
            )
          : (
            <>
              <StyledTable>
                <thead>
                  <TableRow>
                    <TableHeader>Claim No</TableHeader>
                    <TableHeader>Benefit</TableHeader>
                    <TableHeader>Created At</TableHeader>
                    <TableHeader>Status</TableHeader>
                    <TableHeader>Action</TableHeader>
                  </TableRow>
                </thead>
                <tbody>
                  {dataClaims.map((val, index) => (
                    <TableRow key={index}>
                      <TableCell>{val.claim_no}</TableCell>
                      <TableCell>{val.benefit}</TableCell>
                      <TableCell>{val.created_at}</TableCell>
                      <TableCell>{val.status}</TableCell>
                      <TableCell align='center'>
                        <ActionButton onClick={() => history.push(`/claims/${val.claim_id}`)}>Detail</ActionButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </tbody>
              </StyledTable>

              <PaginationContainer>
                <PageButton disabled={currentPage === 1} onClick={() => handlePaginationChange(currentPage - 1)}>Prev</PageButton>
                <span>Page {currentPage} of {numPage}</span>
                <PageButton disabled={currentPage === numPage} onClick={() => handlePaginationChange(currentPage + 1)}>Next</PageButton>
              </PaginationContainer>
            </>
            )}
      </TableContainer>
      )
    : null
}

export default connect(
  (state) => ({
    data: state.Claims.data,
    getClaimListsStatus: state.Claims.getClaimListsStatus,
    claimListsError: state.Error.GET_CLAIM_LISTS,
    claimListsMessage: state.Claims.getClaimListsMessage
  }),
  {
    getClaimLists,
    resetReduxStateClaim
  }
)(ClaimListComponent)
