import React from 'react'
import { connect } from 'react-redux'
import {
  Modal,
  Button,
  Radio,
  Spin,
  Col,
  Row,
  Alert,
  Collapse,
  Icon,
  Checkbox
} from 'antd'
import agentActions from '../../../../../redux/agent/actions'
import AlertLimit from '../../../../../../components/limitAlert'
import ClaimPopupWrapper from './index.style'
import ModalClaimConfirmation from '../ModalClaimConfirmation'
import loadingActions from '../../../../../../redux/loading/actions'
import errorActions from '../../../../../../redux/error/actions'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const Panel = Collapse.Panel
const RadioGroup = Radio.Group
const { validateClaim, getBenefits, createClaim, resetAgentRedux } = agentActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class ClaimPopup extends React.Component {
  state = {
    isClaimActive: false,
    loader: false,
    displaySafeMessage: false,
    skipPreCheck: false
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      dataValidate,
      claimValidateLoading,
      claimValidateError,
      claimValidateStatus,
      claimId,
      createClaimStatus,
      createClaimLoading,
      createClaimError
    } = nextProps
    const { history } = this.props
    if (!claimValidateLoading && !claimValidateError && claimValidateStatus) {
      const {
        message,
        claim_id: existingClaimdId,
        is_claimable: isClaimable,
        is_first_claim: isFirstClaim
      } = dataValidate
      if (!existingClaimdId && isFirstClaim) {
        this.createClaim()
      } else if (existingClaimdId) {
        history.push(`/claims/${existingClaimdId}`)
        this.props.resetAgentRedux()
      } else if (!existingClaimdId && !isFirstClaim && !isClaimable) {
        this.setState({
          displaySafeScreen: true
        })
        return
      } else {
        this.setState({
          showValidatePopup: true,
          validatePopupMessage: message
        })
      }
    }
    if (!createClaimLoading && !createClaimError && createClaimStatus && claimId) {
      history.push(`/claims/${claimId}`)
      this.props.resetAgentRedux(['createClaimStatus'])
    }
  }

  componentWillUnmount () {
    this.props.resetAgentRedux([
      'createClaimStatus',
      'claimValidateStatus',
      'claimValidateStatusCode',
      'createClaimError',
      'claimValidateError'
    ])
  }

  componentDidMount () {
    const { packageName, isClaimOpen, productCode, providerCode, internalId, applicationNo } = this.props
    if (isClaimOpen && packageName !== undefined) {
      this.props.getBenefits({
        package_code: packageName,
        product_key: productCode,
        insurance_provider: providerCode,
        internal_id: internalId,
        application_no: applicationNo
      })
    }
  }

  handleCancel = () => {
    this.props.resetAgentRedux()
    this.props.triggerClosePopup()
  }

  handleCancelClaimValidation = () => {
    this.setState({ showValidatePopup: false })
  }

  handleOkClaimValidation = () => {
    this.createClaim()
    this.handleCancelClaimValidation()
  }

  handleChange = (e) => {
    this.setState({
      value: e.target.value,
      btnLoading: false
    })
  }

  handleCheckChange = (e) => {
    this.setState({ skipPreCheck: e.target.checked })
  }

  createClaim = () => {
    const { isClaimActive, value, skipPreCheck } = this.state
    const { internalId } = this.props
    if (isClaimActive) {
      this.props.createClaim({
        benefit_id: value,
        internal_id: internalId,
        skip_precheck: skipPreCheck,
        source: 'control-panel'
      })
      this.props.resetErrorRedux(['CLAIM_VALIDATE'])
      this.props.resetLoadingRedux(['CLAIM_VALIDATE'])
      this.props.resetAgentRedux(['claimValidateStatus'])
    } else {
      this.setState({ displaySafeMessage: true })
    }
  }

  handleValidate = () => {
    const { internalId } = this.props
    const { value } = this.state
    this.props.validateClaim({
      benefit_id: value,
      internal_id: internalId
    })
  }

  safeScreen = () => {
    return (
      <div>
        <h3>You are in proper protection</h3>
        <p>For more detailed information, contact our customer service at the number below &amp; register your claim.</p>
        <span className='text-font-size-24'>
          <i className='fas fa-phone-volume' />&nbsp;&nbsp;021 3044 8080
        </span>
        <br />
        <br />
        - OR -
        <br />
        <br />
        <p>Chat with PasarPolis customer service team through a Whatsapp number below &amp; submit you claims</p>
        <span className='text-font-size-24'>
          <i className='fab fa-whatsapp' /> &nbsp;&nbsp;0877 0017 8000
        </span>
      </div>
    )
  }

  onCloseDisplayError = () => {
    this.props.removeDisplayError()
  }

  genExtra = () => (
    <Icon type='down' />
  )

  isActive = status => {
    this.setState({ isClaimActive: status })
  }

  renderUnSafeScreen = (getBenefitsLoading, claimBenefitsData) => (
    <Spin spinning={!!getBenefitsLoading} tip='Loading...'>
      {
        (claimBenefitsData !== undefined && claimBenefitsData.length > 0) && (
          <RadioGroup
            onChange={this.handleChange}
            value={this.state.value}
            className='benefits-radio radioWrapperHeightAuto'
          >
            {
              claimBenefitsData.map((val, index) => {
                if (val.benefits.length > 1) {
                  return (
                    <Collapse key={index}>
                      <Panel
                        header={
                          <div className='benefits-collapse-header'>
                            <b>{val.benefit_group_name} </b>
                            <br />
                            <span>{val.benefit_group_description}</span>
                          </div>
                        }
                        key={index}
                        extra={this.genExtra()}
                      >
                        {
                          val.benefits.map((value, i) => {
                            return (
                              <Radio
                                key={i}
                                value={value.benefit_id}
                                onChange={() => this.isActive(value.is_claim_active)}
                              >
                                <b>{value.benefit_name}</b>
                              </Radio>
                            )
                          })
                        }
                      </Panel>
                    </Collapse>
                  )
                } else {
                  return val.benefits.map((value, i) => {
                    return (
                      <div key={i} className='radio-content-wrapper'>
                        <Radio
                          key={i}
                          value={value.benefit_id}
                          onChange={() => this.isActive(value.is_claim_active)}
                        >
                          <b>{value.benefit_name}</b>
                          <br />
                          <span className='description'>{value.description}</span>
                        </Radio>
                        <br />
                      </div>
                    )
                  })
                }
              })
            }
          </RadioGroup>
        )
      }
      {
        (claimBenefitsData !== undefined && claimBenefitsData.length < 1) && (
          <h3>Benefit is not found</h3>
        )
      }
    </Spin>
  )

  render () {
    const {
      isClaimOpen,
      agentClaimBenefitsData,
      createClaimStatus,
      getBenefitsLoading,
      claimValidateLoading,
      claimValidateError,
      claimValidateStatus,
      claimValidateStatusCode,
      createClaimLoading,
      createClaimError
    } = this.props
    const {
      value,
      isClaimActive,
      showValidatePopup,
      validatePopupMessage,
      displaySafeScreen,
      skipPreCheck
    } = this.state
    return (
      <>
        <ModalClaimConfirmation
          isOpen={showValidatePopup}
          message={validatePopupMessage}
          onOk={this.handleOkClaimValidation}
          onCancel={this.handleCancelClaimValidation}
          loading={createClaimLoading}
        />
        <Modal
          title='Benefits'
          visible={isClaimOpen}
          onCancel={this.handleCancel}
          maskClosable={false}
          closable={false}
          footer={[
            <Button key={1} onClick={this.handleCancel}>Cancel</Button>,
            <Button
              key={2}
              disabled={!value || !isClaimActive || claimValidateLoading || getBenefitsLoading || createClaimLoading}
              onClick={this.handleValidate}
              loading={claimValidateLoading || getBenefitsLoading || createClaimLoading}
            >
              Claim
            </Button>
          ]}
          wrapClassName='benefits-modal'
        >
          <ClaimPopupWrapper>
            {
              (!claimValidateLoading && claimValidateError && claimValidateStatus) &&
              (
                claimValidateStatusCode === 'CLAIM_109'
                  ? <AlertLimit message={claimValidateStatus} />
                  : <Alert message={claimValidateStatus} type='error' />
              )

            }
            {
              value && !isClaimActive && (
                <Alert
                  message='Claim is not active for this benefit'
                  type='error'
                />
              )
            }
            {
              (!createClaimLoading && !!createClaimError && createClaimStatus) && (
                <Row className='row-width'>
                  <Col span={24}>
                    <Alert
                      message={createClaimStatus}
                      type='error'
                    />
                  </Col>
                </Row>
              )
            }
            <Spin
              spinning={!!getBenefitsLoading || !!claimValidateLoading || !!createClaimLoading}
              tip='Please wait...'
              className='loader-row'
            >
              {
                displaySafeScreen ? this.safeScreen() : this.renderUnSafeScreen(getBenefitsLoading, agentClaimBenefitsData)
              }
            </Spin>
            <PermissionCheckerV2 requiredPermission='ops.view_agency_create_claim'>
              <Checkbox
                className='checkbox-margin'
                defaultValue={skipPreCheck}
                onChange={this.handleCheckChange}
              >
                Skip Precheck
              </Checkbox>
            </PermissionCheckerV2>
          </ClaimPopupWrapper>
        </Modal>
      </>
    )
  }
}

export default connect(
  state => ({
    claimId: state.Agent.claimId,
    agentClaimBenefitsData: state.Agent.agentClaimBenefitsData,
    getAgentClaimBenefitsStatus: state.Agent.getAgentClaimBenefitsStatus,
    createClaimStatus: state.Agent.createClaimStatus,
    dataValidate: state.Agent.dataValidate,
    claimValidateStatus: state.Agent.claimValidateStatus,
    claimValidateStatusCode: state.Agent.claimValidateStatusCode,
    getBenefitsLoading: state.Loading.GET_AGENT_BENEFITS,
    getBenefitsError: state.Error.GET_AGENT_BENEFITS,
    claimValidateLoading: state.Loading.AGENT_CLAIM_VALIDATE,
    claimValidateError: state.Error.AGENT_CLAIM_VALIDATE,
    createClaimLoading: state.Loading.CREATE_AGENT_CLAIM,
    createClaimError: state.Error.CREATE_AGENT_CLAIM
  }),
  {
    getBenefits,
    resetAgentRedux,
    validateClaim,
    createClaim,
    resetLoadingRedux,
    resetErrorRedux
  }
)(ClaimPopup)
