import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, Row, Col } from 'antd'
import agentAction from '../../../../../redux/agent/actions'
import { ImageMetaDataStyle } from './index.style'
import { connect } from 'react-redux'
import CircularLoader from '../../../../../../components/CircularLoader'
import { convertCamelCaseToString } from '../../../../../../helpers/utility'
import { isEmpty } from 'lodash'
import ErrorBoundary from '../../../../../../components/ErrorBoundary'

const { getImageMetaData, resetAgentRedux } = agentAction

class ImageMetaDataModal extends Component {
  static propTypes = {
    isShowModal: PropTypes.bool,
    imageId: PropTypes.string,
    onCancel: PropTypes.func
  }

  componentDidMount () {
    const { imageId } = this.props
    const img = document.getElementsByClassName(imageId)[0] || document.getElementById(imageId)
    this.props.getImageMetaData({
      url: img.src || img.href
    })
  }

  getImgMetaContainer = () => {
    const { imageMetaData = {} } = this.props
    const imageData = []
    const { metadata = {} } = imageMetaData
    if (isEmpty(metadata)) {
      return (
        <div className='img-meta-title'>
          Meta Data does not exist!
        </div>
      )
    }
    for (const key in metadata) {
      const item = metadata[key]
      if (!(item instanceof Object)) {
        imageData.push(this.getTitleValueContainer(key, item))
      }
    }
    return imageData
  }

  getTitleValueContainer = (title, value) => {
    return (
      <Row type='flex' className='img-meta-row'>
        <Col span={14} className='img-meta-title'>{convertCamelCaseToString(title)}</Col>
        <Col>{Array.isArray(value) ? value.join(', ') : value}</Col>
      </Row>
    )
  }

  render () {
    const { isShowModal, onCancel, imageMetaDataLoader } = this.props
    return (
      <Modal
        title='Image Meta Data'
        visible={isShowModal}
        onCancel={onCancel}
        onOk={onCancel}
        confirmLoading={imageMetaDataLoader}
      >
        <CircularLoader isSpining={imageMetaDataLoader}>
          <ErrorBoundary>
            <ImageMetaDataStyle>
              {
                this.getImgMetaContainer()
              }
            </ImageMetaDataStyle>
          </ErrorBoundary>
        </CircularLoader>
      </Modal>
    )
  }
}

export default connect(
  state => ({
    imageMetaData: state.Agent.imageMetaData,
    imageMetaDataStatus: state.Agent.imageMetaDataStatus,
    imageMetaDataLoader: state.Loading.GET_IMAGE_META_DATA
  }),
  {
    getImageMetaData,
    resetAgentRedux
  }
)(ImageMetaDataModal)
