/* eslint-disable react-hooks/exhaustive-deps */
import get from 'lodash/get'
import { useCallback } from 'react'
import ObjectTable from '../ObjectTable'

function MarineCargoObjectDetails (props) {
  const agentPolicy = get(props, 'agentPolicy.request')

  const getTransportType = useCallback((transportType) => {
    switch (transportType) {
      case 'land':
        return 'Darat'
      case 'sea':
        return 'Laut'
      case 'air':
        return 'Udara'
      default:
        return ''
    }
  }, [])

  const getNameOrKeyForDropdown = useCallback((data, key, valCode = 'value') => {
    if (get(data, `${key}_data`, '')) {
      return get(data, `${key}_data.${valCode}`, '-')
    } else {
      return get(data, key, '-')
    }
  }, [])

  const getCargoInsuredDetails = useCallback(() => {
    const transportType = get(agentPolicy, 'transportation_type')
    let transportDetail = []
    const pickupAddr = get(agentPolicy, 'pickup_address', {})
    const deliveryAddr = get(agentPolicy, 'delivery_address', {})
    switch (transportType) {
      case 'land':
        transportDetail = [
          {
            key: 'insuredData_1',
            name: 'Vehicle Type',
            value: getNameOrKeyForDropdown(agentPolicy, 'vehicle_type')
          },
          {
            key: 'insuredData_2',
            name: 'Vehicle Number',
            value: `${get(agentPolicy, 'region_code', '-')} ${get(agentPolicy, 'vehicle_plate_no', '-')}`
          }
        ]
        break
      case 'sea':
        transportDetail = [
          {
            key: 'insuredData_3',
            name: 'Ship type',
            value: getNameOrKeyForDropdown(agentPolicy, 'ship_type')
          },
          {
            key: 'insuredData_4',
            name: 'Ship material',
            value: getNameOrKeyForDropdown(agentPolicy, 'ship_material')
          },
          {
            key: 'insuredData_5',
            name: 'Ship Class',
            value: getNameOrKeyForDropdown(agentPolicy, 'ship_class')
          },
          {
            key: 'insuredData_6',
            name: 'Manufacturing Year',
            value: get(agentPolicy, 'year', '-')
          },
          {
            key: 'insuredData_7',
            name: 'Country',
            value: getNameOrKeyForDropdown(agentPolicy, 'country', 'country_name')
          }
        ]
        break
      case 'air':
        transportDetail = [
          {
            key: 'insuredData_7',
            name: 'Airplane Registration no',
            value: get(agentPolicy, 'plane_registration_no', '-')
          },
          {
            key: 'insuredData_8',
            name: 'Airplane Name',
            value: get(agentPolicy, 'airplane_name', '-')
          },
          {
            key: 'insuredData_9',
            name: 'Flight No',
            value: get(agentPolicy, 'flight_no', '-')
          }
        ]
        break
      default:
    }

    return [
      {
        key: 'insuredData_10',
        name: 'Mode of Transport',
        value: getTransportType(get(agentPolicy, 'transportation_type', ''))
      },
      ...transportDetail,
      {
        key: 'insuredData_13',
        name: 'Insured Business',
        value: get(agentPolicy, 'insured_business', '-')
      },
      {
        key: 'insuredData_14',
        name: 'Travel No',
        value: get(agentPolicy, 'travel_number', '-')
      },
      {
        key: 'insuredData_15',
        name: 'Recipient Name',
        value: get(agentPolicy, 'recipient_name', '-')
      },
      {
        key: 'insuredData_16',
        name: 'Pickup Address',
        value: `${get(pickupAddr, 'address')}, ${get(pickupAddr, 'city_name')} ${get(pickupAddr, 'postal_code')}, ${get(pickupAddr, 'province_name')}`
      },
      {
        key: 'insuredData_17',
        name: 'Delivery Address',
        value: `${get(deliveryAddr, 'address')}, ${get(deliveryAddr, 'city_name')} ${get(deliveryAddr, 'postal_code')}, ${get(deliveryAddr, 'province_name')}`
      }
    ]
  }, [agentPolicy])

  return (
    <ObjectTable
      title='Object Insured Details'
      tableColumns={getCargoInsuredDetails()}
    />
  )
}

export default MarineCargoObjectDetails
