import get from 'lodash/get'
import moment from 'moment-timezone'
import { getAddressFromObj } from '../../../utility'
import ObjectTable from '../../ObjectTable'
import isVNPath from '../../../../../../../helpers/isVNPath'

function PolicyHolderDetails (props) {
  const { policyDetail } = props
  const ktpAddr = get(policyDetail, 'request.customer_data.customer_address', {})
  const resAddr = get(policyDetail, 'request.residence_address', {})

  const data = [
    {
      key: 'holder_1',
      name: <strong>Name</strong>,
      value: get(policyDetail, 'request.customer_data.name', '')
    },
    {
      key: 'holder_2',
      name: <strong>{isVNPath() ? 'ID' : 'KTP/KK Number'}</strong>,
      value: get(policyDetail, 'request.ktp_no', '')
    },
    {
      key: 'holder_3',
      name: <strong>Email</strong>,
      value: get(policyDetail, 'request.customer_data.email', '')
    },
    {
      key: 'holder_4',
      name: <strong>Phone Number</strong>,
      value: get(policyDetail, 'request.customer_data.mobile_no', '')
    },
    {
      key: 'holder_5',
      name: <strong>Place, Date of Birth</strong>,
      value: `${get(policyDetail, 'request.birth_place', '')},${moment(get(policyDetail, 'request.dob', ''), 'YYYY-MM-DD').format('DD MMMM YYYY')}`
    },
    {
      key: 'holder_6',
      name: <strong>Gender</strong>,
      value: get(policyDetail, 'request.gender_data.value', '')
    },
    {
      key: 'holder_7',
      name: <strong>Occupation Status</strong>,
      value: get(policyDetail, 'request.working_status_data.value', '')
    },
    {
      key: 'holder_8',
      name: <strong>Policy Holder Address on KTP/KK</strong>,
      value: getAddressFromObj(ktpAddr)
    },
    {
      key: 'holder_9',
      name: <strong>Policy Holder Residence Address</strong>,
      value: getAddressFromObj(resAddr)
    }
  ]

  return (
    <ObjectTable
      title='Policy Holder'
      tableColumns={data}
    />
  )
}

export default PolicyHolderDetails
