import React, { Component, Fragment } from 'react'
import PropTypes from 'prop-types'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { Table } from 'antd'

class ObjectTable extends Component {
  static propTypes = {
    title: PropTypes.object,
    tableColumns: PropTypes.array // this contains { id, name, value }
  }

  render () {
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      },
      {
        dataIndex: 'value',
        render: (value, { name }) => {
          if (value && (name === 'Details')) {
            return value.split('/n').map((item, index) => (
              <Fragment key={`details_${index}`}> {item}<br /></Fragment>
            ))
          }
          return value
        }
      },
      {
        dataIndex: 'value1',
        render: (value, { name }) => {
          if (value && (name === 'Details')) {
            return value.split('/n').map((item, index) => (
              <Fragment key={`details_${index}`}> {item}<br /></Fragment>
            ))
          }
          return value
        }
      }

    ]
    const { tableColumns, title } = this.props

    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>{title}</h3>
          <Table
            pagination={false}
            rowKey={data => data.id}
            showHeader={false}
            columns={columns}
            dataSource={tableColumns}
          />
        </div>
      </LayoutContentStyle>
    )
  }
}

export default ObjectTable
