import { Modal } from 'antd'
import React from 'react'
import { EmailScreenShotStyle } from './index.style'
import getUrlExtension from '../../../../../helpers/getExtensionUrl'

function UploadImageConfirmationModal (props) {
  const {
    show, onClose, onUpload, file, title,
    confirmationText, okText, cancelText, loader
  } = props

  return (
    <Modal
      visible={show}
      onCancel={onClose}
      onOk={onUpload}
      cancelText={cancelText || 'Cancel'}
      okText={okText || 'Upload'}
      title={title}
      okButtonProps={{
        loading: loader
      }}
    >
      <EmailScreenShotStyle>
        {
          confirmationText && (
            <div>{confirmationText}</div>
          )
        }
        {
          (getUrlExtension(file) === 'pdf')
            ? (
              <object
                type='application/pdf'
                data={file}
                height='300'
                width='300'
                aria-label='PDF'
              />
              )
            : <img className='file-img' src={file} alt='file' />
        }
      </EmailScreenShotStyle>
    </Modal>
  )
}

export default UploadImageConfirmationModal
