import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, Row, Input, Col, Form } from 'antd'

class PendingOnAgentModel extends Component {
  static propTypes = {
    isShowModal: PropTypes.bool,
    onSubmit: PropTypes.func,
    onCancel: PropTypes.func
  };

  state = {
    documentPending: ''
  };

  handleDocumentPending = (e) => {
    this.setState({
      documentPending: e.target.value
    })
  };

  handleCustomSubmit = () => {
    this.props.onSubmit(this.state.documentPending)
  };

  render () {
    const { isShowModal, onCancel } = this.props
    return (
      <Modal
        title='Document Pending On Mitra'
        visible={isShowModal}
        onOk={this.handleCustomSubmit}
        onCancel={onCancel}
        okText='Submit'
      >
        <Row>
          <Col>
            <Form.Item>
              <Input.TextArea
                placeholder='Input details of documents/photos pending on mitra'
                onChange={(e) => this.handleDocumentPending(e)}
              />
            </Form.Item>
          </Col>
        </Row>
      </Modal>
    )
  }
}

export default PendingOnAgentModel
