import { useEffect } from 'react'
import PropTypes from 'prop-types'
import { Input, Select } from 'antd'
import {
  toUpper,
  digitsOnly,
  lettersAndSpaces,
  normalizePlate,
  validators
} from './helpers'

const DynamicForm = ({
  editableFieldKey,
  editableFieldUserInput,
  onChangeInput,
  onValidate,
  regionCode
}) => {
  // compute validity and notify parent when input/key changes
  useEffect(() => {
    if (typeof onValidate !== 'function') return
    const value = (editableFieldUserInput || '')
    const validator = validators[editableFieldKey]
    const isValid = validator ? validator(value) : value !== undefined && value !== ''
    onValidate(isValid)
  }, [editableFieldKey, editableFieldUserInput, onValidate])
  const renderField = () => {
    switch (editableFieldKey) {
      case 'transmission_type':
        return (
          <Select
            placeholder='Select option'
            value={editableFieldUserInput}
            onChange={val => onChangeInput(val)}
            id={`editable-input-${editableFieldKey}`}
            style={{ width: '100%' }}
          >
            <Select.Option value='Automatic'>Automatic</Select.Option>
            <Select.Option value='Manual'>Manual</Select.Option>
          </Select>
        )
      case 'chasis_number': {
        const value = (editableFieldUserInput || '')
        const vin = toUpper(value).trim()
        const errorMessage = vin.length > 0 && !validators.chasis_number(value)
          ? 'Chassis number must be 8-20 characters (letters and numbers only). No spaces or special characters.'
          : ''

        return (
          <div>
            <Input
              placeholder='Enter Chasis Number..'
              value={editableFieldUserInput}
              onChange={e => onChangeInput(toUpper(e.target.value))}
              onPaste={e => {
                e.preventDefault()
                onChangeInput(toUpper(e.clipboardData && e.clipboardData.getData('text')))
              }}
              id={`editable-input-${editableFieldKey}`}
            />
            {errorMessage && (
              <div style={{ color: '#f5222d', marginTop: 6, fontSize: 12 }}>
                {errorMessage}
              </div>
            )}
          </div>
        )
      }
      case 'machine_number': {
        const value = (editableFieldUserInput || '')
        const machineNumber = toUpper(value).trim()
        const errorMessage = machineNumber.length > 0 && !validators.machine_number(value)
          ? 'Machine number must be 5-21 characters and may contain only letters and numbers.'
          : ''

        return (
          <div>
            <Input
              placeholder='e.g. 1TRR7192327 or 4D34T432101'
              value={editableFieldUserInput}
              onChange={e => onChangeInput(toUpper(e.target.value))}
              onPaste={e => {
                e.preventDefault()
                onChangeInput(toUpper(e.clipboardData && e.clipboardData.getData('text')))
              }}
              id={`editable-input-${editableFieldKey}`}
            />
            <div style={{ color: '#8c8c8c', marginTop: 6, fontSize: 12 }}>
              Examples: 1TRR7192327, 4D34T432101
            </div>
            {errorMessage && (
              <div style={{ color: '#f5222d', marginTop: 6, fontSize: 12 }}>
                {errorMessage}
              </div>
            )}
          </div>
        )
      }
      case 'vehicle_plate_no': {
        const region = regionCode || ''
        const raw = (editableFieldUserInput || '')
        const plate = normalizePlate(raw)
        const showError = plate.length > 0 && !validators.vehicle_plate_no(raw)
        const errorMessage = showError
          ? 'Plate is required'
          : ''

        return (
          <div>
            <div style={{ display: 'flex', gap: 8 }}>
              <Input
                value={region}
                disabled
                style={{ width: 120, background: '#f5f5f5' }}
                id={`editable-input-${editableFieldKey}-region`}
              />
              <Input
                placeholder='e.g. 1234ABC'
                value={editableFieldUserInput}
                onChange={e => onChangeInput(normalizePlate(e.target.value))}
                onPaste={e => {
                  e.preventDefault()
                  onChangeInput(normalizePlate(e.clipboardData && e.clipboardData.getData('text')))
                }}
                id={`editable-input-${editableFieldKey}`}
                style={{ flex: 1 }}
              />
            </div>
            <div style={{ color: '#8c8c8c', marginTop: 6, fontSize: 12 }}>
              Example: 1234ABC
            </div>
            {errorMessage && (
              <div style={{ color: '#f5222d', marginTop: 6, fontSize: 12 }}>
                {errorMessage}
              </div>
            )}
          </div>
        )
      }
      case 'ktp_no': {
        const value = (editableFieldUserInput || '')
        const showError = value.length > 0 && !validators.ktp_no(value)

        return (
          <div>
            <Input
              placeholder='Enter KTP No..'
              value={editableFieldUserInput}
              onChange={e => onChangeInput(digitsOnly(e.target.value).slice(0, 16))}
              onPaste={e => {
                e.preventDefault()
                onChangeInput(digitsOnly(e.clipboardData && e.clipboardData.getData('text')).slice(0, 16))
              }}
              id={`editable-input-${editableFieldKey}`}
              maxLength={16}
              inputMode='numeric'
            />
            {showError && (
              <div style={{ color: '#f5222d', marginTop: 6, fontSize: 12 }}>
                KTP number must be exactly 16 digits
              </div>
            )}
          </div>
        )
      }
      case 'color': {
        return (
          <div>
            <Input
              placeholder='Enter color..'
              value={editableFieldUserInput}
              onChange={e => onChangeInput(lettersAndSpaces(e.target.value))}
              onPaste={e => {
                e.preventDefault()
                onChangeInput(lettersAndSpaces(e.clipboardData && e.clipboardData.getData('text')))
              }}
              id={`editable-input-${editableFieldKey}`}
            />
            <div style={{ color: '#8c8c8c', marginTop: 6, fontSize: 12 }}>
              Letters and spaces only
            </div>
          </div>
        )
      }
      default:
        return (
          <Input
            placeholder='Enter new value..'
            value={editableFieldUserInput}
            onChange={e => onChangeInput(e.target.value)}
            id={`editable-input-${editableFieldKey}`}
          />
        )
    }
  }

  return <div className='dynamic-form-field'>{renderField()}</div>
}

DynamicForm.propTypes = {
  editableFieldKey: PropTypes.string.isRequired,
  editableFieldValue: PropTypes.any,
  editableFieldUserInput: PropTypes.any,
  onChangeInput: PropTypes.func.isRequired,
  onValidate: PropTypes.func
}

DynamicForm.defaultProps = {
  editableFieldValue: '',
  editableFieldUserInput: ''
}

export default DynamicForm
