/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback } from 'react'
import { DATE_FIELDS } from '../../constants'
import { Row, Col } from 'antd'
import get from 'lodash/get'

function Dates (props) {
  const {
    renderFormElementInRow, isPreview = false,
    isDetail, reviewData
  } = props

  const renderDates = useCallback(() => {
    return (
      renderFormElementInRow(DATE_FIELDS)
    )
  }, [renderFormElementInRow])

  const renderPreviewDates = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        {
          DATE_FIELDS.map((df, index) => (
            <Col
              key={`formview_${index}`}
              className={`form-col-width ${(index + 1) !== DATE_FIELDS.length && 'field-margin'}`}
            >
              <h3>
                {df.title}
              </h3>
              <div>
                {
                  isDetail
                    ? get(reviewData, df.name)
                    : get(reviewData, df.name).format('DD/MM/YYYY')
                }
              </div>
            </Col>
          ))
        }
      </Row>
    )
  }, [reviewData])

  return (
    <div>
      {
        isPreview || isDetail
          ? <h2>Dates</h2>
          : <h3>Dates</h3>
      }
      {
        isPreview || isDetail
          ? renderPreviewDates()
          : renderDates()
      }

    </div>
  )
}

export default Dates
