import React from 'react'
import {
  Row,
  Col,
  Table
} from 'antd'
import { capitalizeFirstLetter } from '../../../../helpers/utility'
import LayoutContent from '../../../../components/utility/layoutContent'
import { get } from 'lodash'

class TravelObjectDetail extends React.Component {
  render () {
    const { additionalDetail, agentPolicy } = this.props

    const calculateRestOfFamilyMembers = (family) => {
      const { kids = 0, adult = 0 } = family

      return (kids + adult)
    }
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value'
      }
    ]
    let columnPolicyDetailsReq = []

    const extraDetails = {
      coverage_area: get(additionalDetail, 'travel_type') === 'international' ? 'International - Worldwide/ ASEAN' : 'Domestic',
      source: get(additionalDetail, 'source'),
      destination: get(additionalDetail, 'destination', []).join(', '),
      travel_start_date: get(agentPolicy, 'request.start_date', ''),
      travel_end_date: get(agentPolicy, 'request.end_date', ''),
      type_of_insured: get(additionalDetail, 'policy_type'),
      no_of_insured_individual: 1 + calculateRestOfFamilyMembers(get(additionalDetail, 'extra_data.additional_member_count')),
      package_name: get(agentPolicy, 'provider_package.package.name', ''),
      policy_type: 'Single Trip'
    }

    for (const key in extraDetails) {
      columnPolicyDetailsReq = [
        ...columnPolicyDetailsReq, {
          key,
          name: <strong>{capitalizeFirstLetter(key)}</strong>,
          value: extraDetails[key] !== undefined ? extraDetails[key] : '-'
        }
      ]
    }

    return (
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title'>Object Insured Details Travel</h3>
          <Col span={24}>
            <Table
              pagination={{ pageSize: 100 }}
              showHeader={false}
              columns={columns}
              dataSource={columnPolicyDetailsReq}
            />
          </Col>
        </Row>
      </LayoutContent>
    )
  }
}
export default TravelObjectDetail
