import get from 'lodash/get'
import moment from 'moment-timezone'
import { getAddressFromObj } from '../../../utility'
import ObjectTable from '../../ObjectTable'
import isVNPath from '../../../../../../../helpers/isVNPath'

function InsuredDetails (props) {
  const { policyDetail } = props
  const ktpAddr = get(policyDetail, 'request.insured_details.customer_data.customer_address', {})
  const resAddr = get(policyDetail, 'request.insured_details.residence_address', {})

  const data = [
    {
      key: 'insured_1',
      name: <strong>Name</strong>,
      value: get(policyDetail, 'request.insured_details.customer_data.name', '')
    },
    {
      key: 'insured_2',
      name: <strong>{isVNPath() ? 'ID' : 'KTP/KK Number'}</strong>,
      value: get(policyDetail, 'request.insured_details.id_no', '')
    },
    {
      key: 'insured_3',
      name: <strong>Email</strong>,
      value: get(policyDetail, 'request.insured_details.customer_data.email', '')
    },
    {
      key: 'insured_4',
      name: <strong>Phone Number</strong>,
      value: get(policyDetail, 'request.insured_details.customer_data.mobile_no', '')
    },
    {
      key: 'insured_5',
      name: <strong>Place, Date of Birth</strong>,
      value: `${get(policyDetail, 'request.insured_details.birth_place', '')},${moment(get(policyDetail, 'request.insured_details.dob', ''), 'YYYY-MM-DD').format('DD MMMM YYYY')}`
    },
    {
      key: 'insured_6',
      name: <strong>Gender</strong>,
      value: get(policyDetail, 'request.insured_details.gender_data.value', '')
    },
    {
      key: 'insured_7',
      name: <strong>Occupation Type</strong>,
      value: get(policyDetail, 'request.occupation_type_data.value', '')
    },
    {
      key: 'insured_8',
      name: <strong>Relation With Policy Holder</strong>,
      value: get(policyDetail, 'request.relation_data.value', '')
    },
    {
      key: 'insured_9',
      name: <strong>Coverage Period</strong>,
      value: `${get(policyDetail, 'payment_detail.proposed_coverage_start', '-')} to ${get(policyDetail, 'payment_detail.proposed_coverage_end', '-')}`
    },
    {
      id: 'insured_10',
      name: <strong>Pay Later</strong>,
      value: get(policyDetail, 'request.use_pay_later', '-') ? 'Yes' : 'No'
    },
    {
      key: 'insured_11',
      name: <strong>Insured Address on KTP/KK</strong>,
      value: getAddressFromObj(ktpAddr)
    },
    {
      key: 'insured_12',
      name: <strong>Insured Residence Address</strong>,
      value: getAddressFromObj(resAddr)
    }
  ]

  return (
    <ObjectTable
      title='Policy Details'
      tableColumns={data}
    />
  )
}

export default InsuredDetails
